contracts/AirdropDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title AirdropDistributor
 * @notice Helper contract for batch token distributions (airdrops)
 * @dev Transfers tokens from distributor's wallet to multiple recipients atomically
 * 
 * Key Features:
 * - Pre-validates allowance and balance BEFORE loop (fails fast, saves gas)
 * - Atomic execution: all transfers succeed or entire transaction reverts
 * - ReentrancyGuard for security
 * - Emits detailed event for tracking
 * 
 * Usage Flow:
 * 1. Token creator withdraws from vesting contract (if needed)
 * 2. Token creator approves AirdropDistributor for total amount
 * 3. Token creator calls batchTransfer() with recipients and amounts
 */
contract AirdropDistributor is ReentrancyGuard {

    /**
     * @notice Emitted when a batch airdrop is successfully distributed
     * @param token The ERC20 token contract address
     * @param distributor The wallet that initiated the distribution
     * @param recipientCount Number of recipients
     * @param totalAmount Total tokens distributed
     */
    event AirdropDistributed(
        address indexed token,
        address indexed distributor,
        uint256 recipientCount,
        uint256 totalAmount
    );

    /**
     * @notice Batch transfer tokens to multiple recipients
     * @dev CRITICAL: Pre-validates allowance and balance BEFORE loop to fail fast
     * 
     * @param token The ERC20 token to distribute
     * @param recipients Array of recipient addresses
     * @param amounts Array of token amounts (must match recipients length)
     * 
     * Requirements:
     * - recipients and amounts arrays must have same length
     * - Must have sufficient allowance for this contract
     * - Must have sufficient balance to cover all transfers
     * - All amounts must be > 0
     * - No recipient can be address(0)
     * 
     * Reverts:
     * - "Length mismatch" if arrays don't match
     * - "Empty array" if no recipients
     * - "Invalid amount" if any amount is 0
     * - "Insufficient allowance" if allowance < total
     * - "Insufficient balance" if balance < total
     * - "Invalid recipient" if any recipient is address(0)
     * - "Transfer failed" if any transferFrom fails
     */
    function batchTransfer(
        address token,
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external nonReentrant {
        // Validate array lengths
        require(recipients.length == amounts.length, "Length mismatch");
        require(recipients.length > 0, "Empty array");

        IERC20 tokenContract = IERC20(token);

        // Step 1: Calculate total amount needed
        uint256 totalAmount = 0;
        for (uint256 i = 0; i < amounts.length; i++) {
            require(amounts[i] > 0, "Invalid amount");
            totalAmount += amounts[i];
        }

        // Step 2: Pre-validate allowance (fails fast, not mid-loop)
        uint256 allowance = tokenContract.allowance(msg.sender, address(this));
        require(allowance >= totalAmount, "Insufficient allowance");

        // Step 3: Pre-validate balance (fails fast, not mid-loop)
        uint256 balance = tokenContract.balanceOf(msg.sender);
        require(balance >= totalAmount, "Insufficient balance");

        // Step 4: Execute transfers (all succeed or entire TX reverts)
        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "Invalid recipient");

            bool success = tokenContract.transferFrom(
                msg.sender,
                recipients[i],
                amounts[i]
            );

            require(success, "Transfer failed");
        }

        // Emit summary event
        emit AirdropDistributed(
            token,
            msg.sender,
            recipients.length,
            totalAmount
        );
    }

    /**
     * @notice Batch transfer equal amounts to all recipients (gas-optimized)
     * @dev Useful when all recipients get the same amount
     * 
     * @param token The ERC20 token to distribute
     * @param recipients Array of recipient addresses
     * @param amountPerRecipient Amount each recipient receives
     */
    function batchTransferEqual(
        address token,
        address[] calldata recipients,
        uint256 amountPerRecipient
    ) external nonReentrant {
        require(recipients.length > 0, "Empty array");
        require(amountPerRecipient > 0, "Invalid amount");

        IERC20 tokenContract = IERC20(token);

        // Calculate total
        uint256 totalAmount = recipients.length * amountPerRecipient;

        // Pre-validate allowance and balance
        require(
            tokenContract.allowance(msg.sender, address(this)) >= totalAmount,
            "Insufficient allowance"
        );
        require(
            tokenContract.balanceOf(msg.sender) >= totalAmount,
            "Insufficient balance"
        );

        // Execute transfers
        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "Invalid recipient");

            bool success = tokenContract.transferFrom(
                msg.sender,
                recipients[i],
                amountPerRecipient
            );

            require(success, "Transfer failed");
        }

        // Emit summary event
        emit AirdropDistributed(
            token,
            msg.sender,
            recipients.length,
            totalAmount
        );
    }
}

contracts/AirdropVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract AirdropVesting is ReentrancyGuard {
    IERC20 public immutable token;
    address public immutable beneficiary;
    uint256 public immutable totalAllocation;
    uint256 public immutable startTime;
    uint256 public constant DAILY_UNLOCK_PCT = 5; // 5% per day
    uint256 public constant VESTING_PERIOD = 20 days;
    uint256 public withdrawn;

    event TokensWithdrawn(address indexed beneficiary, uint256 amount);

    constructor(
        address _token,
        address _beneficiary,
        uint256 _totalAllocation
    ) {
        require(_token != address(0), "Invalid token");
        require(_beneficiary != address(0), "Invalid beneficiary");
        require(_totalAllocation > 0, "Invalid allocation");

        token = IERC20(_token);
        beneficiary = _beneficiary;
        totalAllocation = _totalAllocation;
        startTime = block.timestamp;
    }

    function getUnlockedAmount() public view returns (uint256) {
        uint256 elapsed = block.timestamp - startTime;

        if (elapsed >= VESTING_PERIOD) {
            return totalAllocation; // 100% unlocked after 20 days
        }

        uint256 daysElapsed = elapsed / 1 days;
        uint256 unlocked = (totalAllocation * daysElapsed * DAILY_UNLOCK_PCT) / 100;

        return unlocked > totalAllocation ? totalAllocation : unlocked;
    }

    function getWithdrawableAmount() public view returns (uint256) {
        uint256 unlocked = getUnlockedAmount();
        return unlocked > withdrawn ? unlocked - withdrawn : 0;
    }

    function withdraw() external nonReentrant {
        require(msg.sender == beneficiary, "Only beneficiary can withdraw");

        uint256 withdrawable = getWithdrawableAmount();
        require(withdrawable > 0, "No tokens available");

        withdrawn += withdrawable;

        require(token.transfer(beneficiary, withdrawable), "Transfer failed");
        emit TokensWithdrawn(beneficiary, withdrawable);
    }
}

contracts/BondingCurvePool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

// Interface for GraduationController
interface IGraduationController {
    function initiateGraduation(address tokenAddress) external;
}

contract BondingCurvePool is ERC20, ReentrancyGuard, Pausable, Ownable {
    // Supply distribution
    uint256 public constant CURVE_SUPPLY_PCT = 75;
    uint256 public constant LP_SUPPLY_PCT = 25;
    uint256 public constant MAX_WALLET_PCT = 10;
    uint256 public constant TOTAL_FEE_BPS = 100; // 1% total trading fee
    uint256 public constant CREATOR_SHARE_BPS = 1000; // 10% of fees (0.1% of trade)

    // GRADUATION: Backend oracle calculates USD market cap off-chain
    // Target: $70,000 USD market cap (backend checks: virtualKasReserve * kasPrice >= $70K)
    address public graduationOracle; // Backend oracle address authorized to trigger graduation
    address public graduationController; // GraduationController contract address for DEX migration

    uint256 public constant MIN_TRADE_AMOUNT = 0.001 ether; // Minimum trade size
    uint256 public constant INITIAL_VIRTUAL_KAS = 0.001 ether; // Initial virtual seed (not actual KAS)

    address public treasury; // Gemlaunch treasury contract
    address public airdropTreasury; // Airdrop Treasury for anti-bot fees (70% of anti-bot fees)
    address public platformDevelopmentWallet; // Platform dev wallet (30% of anti-bot fees)
    address public immutable creator; // Token creator address (immutable)

    // AUDIT FIX: Virtual reserves - single source of truth for AMM pricing
    uint256 public virtualKasReserve;   // Tradeable KAS only (excludes fees)
    uint256 public virtualTokenReserve; // Tradeable tokens only

    // Fee tracking (separate from reserves)
    uint256 public accumulatedPlatformFees;
    uint256 public accumulatedCreatorFees;
    uint256 public totalAntiBotFeesCollected; // AUDIT FIX: Total anti-bot fees (analytics only)

    // Anti-Bot System (GEM System - optional per token)
    bool public antiBotEnabled;
    uint256 public deploymentTime; // Launch timestamp

    bool public graduated;
    bool public graduating; // Lock flag during graduation
    bool public liquidityTransferred; // Track if KAS has been transferred to GraduationController
    bool public reserveDistributed; // Track if creator has claimed reserve tokens (one-time only)

    // Additional state for access control
    address public admin;
    address public buybackReserveWallet;
    address public kaspaNetworkSupportWallet;
    address public communityRewardsWallet;

    // PRO Token Vesting Support
    uint8 public reservedPercentage;  // 0-25 (vesting %)
    address public factory;
    mapping(address => bool) public isVestingContract;
    bool public vestingInitialized;

    // AUDIT FIX CR-1: Track vesting contract addresses for on-chain queries
    address public airdropVestingContract;
    address public marketingVestingContract;
    address public teamVestingContract;

    enum VestingType { Airdrop, Marketing, Team }

    // Events
    event TokensPurchased(
        address indexed buyer,
        uint256 tokensOut,
        uint256 tradeAmount,
        uint256 platformFee,
        uint256 creatorFee,
        uint256 antiBotFee
    );

    event TokensSold(
        address indexed seller,
        uint256 tokensIn,
        uint256 kasOut,
        uint256 platformFee,
        uint256 creatorFee
    );

    event AntiBotFeePaid(
        address indexed user,
        uint256 feeAmount,
        uint256 elapsedSeconds
    );

    event AntiBotFeeSplit(
        uint256 leaderboardAmount,
        uint256 platformDevAmount
    );

    event Graduated(address indexed pool, uint256 kasLiquidity, uint256 tokenLiquidity);
    event GraduationCompleted(address indexed pool, uint256 kasLiquidity, uint256 tokenLiquidity);
    event GraduationInitiated(uint256 kasLiquidity, uint256 tokenLiquidity);
    event GraduationCancelled(address indexed pool);
    event UnsoldTokensBurned(uint256 amount);
    event CreatorFeesWithdrawn(address indexed creator, uint256 amount);
    event GraduationOracleUpdated(address indexed newOracle);
    event FeesDistributed(uint256 dev, uint256 buyback, uint256 kaspa, uint256 community);
    event ReserveDistributed(address indexed creator, address[] recipients, uint256[] amounts, uint256 totalDistributed);
    event VestingTransfer(address indexed vestingContract, uint256 amount, VestingType indexed vestingType, uint256 timestamp);
    event VestingFinalized(uint256 timestamp);

    constructor(
        string memory name,
        string memory symbol,
        uint256 totalSupply,
        address _creator,
        address _treasury,
        address _airdropTreasury,
        address _platformDevelopmentWallet,
        bool _antiBotEnabled,
        address _graduationOracle,
        address _graduationController,
        address _admin,
        address _buybackReserve,
        address _kaspaSupport,
        address _communityRewards,
        uint8 _reservedPercentage  // NEW: 0-25 (vesting %)
    ) ERC20(name, symbol) Ownable(msg.sender) {
        require(_creator != address(0), "Invalid creator");
        require(_treasury != address(0), "Invalid treasury");
        require(_airdropTreasury != address(0), "Invalid airdrop treasury");
        require(_platformDevelopmentWallet != address(0), "Invalid platform wallet");
        require(_airdropTreasury != address(this), "Airdrop treasury cannot be self");
        require(_platformDevelopmentWallet != address(this), "Platform wallet cannot be self");
        require(_graduationOracle != address(0), "Invalid graduation oracle");
        require(_graduationController != address(0), "Invalid graduation controller");
        require(_admin != address(0), "Invalid admin");
        require(_buybackReserve != address(0), "Invalid buyback reserve");
        require(_kaspaSupport != address(0), "Invalid kaspa support");
        require(_communityRewards != address(0), "Invalid community rewards");

        // L-2 FIX: Duplicate address validation
        require(_treasury != _admin, "Treasury cannot be admin");
        require(_treasury != _graduationOracle, "Treasury cannot be oracle");
        require(_airdropTreasury != _platformDevelopmentWallet, "Duplicate wallets");

        // PRO Token Vesting validation
        require(_reservedPercentage <= 25, "Vesting exceeds 25%");
        reservedPercentage = _reservedPercentage;
        factory = msg.sender;

        creator = _creator;
        treasury = _treasury;
        airdropTreasury = _airdropTreasury;
        platformDevelopmentWallet = _platformDevelopmentWallet;
        antiBotEnabled = _antiBotEnabled;
        graduationOracle = _graduationOracle;
        graduationController = _graduationController;
        admin = _admin;
        buybackReserveWallet = _buybackReserve;
        kaspaNetworkSupportWallet = _kaspaSupport;
        communityRewardsWallet = _communityRewards;

        // AUDIT FIX: Only set deploymentTime if anti-bot enabled
        if (_antiBotEnabled) {
            deploymentTime = block.timestamp;
        }

        // Mint total supply to contract
        _mint(address(this), totalSupply);

        // CRITICAL: Initialize virtual reserves to prevent division by zero
        // KEY CALCULATION: Curve supply decreases as vesting increases
        // BASIC (0% vesting): curve = 75%, vesting = 0%, LP = 25%
        // PRO (e.g. 20% vesting): curve = 55%, vesting = 20%, LP = 25%
        uint256 curveSupply = totalSupply * (75 - _reservedPercentage) / 100;
        virtualTokenReserve = curveSupply;
        virtualKasReserve = INITIAL_VIRTUAL_KAS; // Virtual seed for initial pricing (not actual KAS)

        // LP tokens (25%) stay in contract, not in virtualTokenReserve
        // Vesting tokens (reservedPercentage%) will be transferred to vesting contracts by factory
    }

    // PRO Token Vesting Functions
    function transferReserveToVesting(
        address vestingContract,
        uint256 amount,
        VestingType vestingType
    ) external nonReentrant {
        require(msg.sender == factory, "Only factory");
        require(!vestingInitialized, "Already finalized");
        require(vestingContract != address(this), "Cannot vest to self");

        // AUDIT FIX CR-1: Track vesting contract by type
        if (vestingType == VestingType.Airdrop) {
            airdropVestingContract = vestingContract;
        } else if (vestingType == VestingType.Marketing) {
            marketingVestingContract = vestingContract;
        } else {
            teamVestingContract = vestingContract;
        }

        // Register for wallet cap exemption
        isVestingContract[vestingContract] = true;

        _transfer(address(this), vestingContract, amount);

        emit VestingTransfer(vestingContract, amount, vestingType, block.timestamp);
    }

    function finalizeVestingSetup() external {
        require(msg.sender == factory, "Only factory");
        require(!vestingInitialized, "Already finalized");

        vestingInitialized = true;
        reserveDistributed = true;

        // C-2 FIX: Verify expected balance after vesting transfers
        // Pool should have: curve supply (virtualTokenReserve) + LP supply (25%)
        uint256 lpSupply = totalSupply() * LP_SUPPLY_PCT / 100;
        uint256 expectedBalance = virtualTokenReserve + lpSupply;
        require(
            balanceOf(address(this)) == expectedBalance,
            "Vesting transfer accounting mismatch"
        );

        emit VestingFinalized(block.timestamp);
    }

    // AUDIT FIX CR-1: View function for on-chain vesting contract queries
    function getVestingContracts() external view returns (
        address airdrop,
        address marketing,
        address team
    ) {
        return (airdropVestingContract, marketingVestingContract, teamVestingContract);
    }

    function buyTokens(uint256 minTokensOut, uint256 deadline) external payable nonReentrant whenNotPaused {
        require(!graduated && !graduating, "Token graduated or graduating");
        require(block.timestamp <= deadline, "Transaction expired");
        require(msg.value >= MIN_TRADE_AMOUNT, "Below minimum trade");

        uint256 remainingValue = msg.value;
        uint256 antiBotFee = 0;

        // AUDIT FIX v4: Step 1 - Calculate and deduct anti-bot fee FIRST
        if (antiBotEnabled && block.timestamp < deploymentTime + 60) {
            uint256 elapsed = block.timestamp - deploymentTime;
            // Linear decay: 95% → 1% over 60 seconds
            uint256 feePercent = 9500 - (9400 * elapsed / 60);
            antiBotFee = msg.value * feePercent / 10000;
            remainingValue = msg.value - antiBotFee;

            // TRANSPARENCY FIX: Split anti-bot fees at contract level (no cross-wallet transfers)
            uint256 leaderboardFee = antiBotFee * 70 / 100;  // 70% → Airdrop/Leaderboard
            uint256 platformDevFee = antiBotFee - leaderboardFee; // 30% → Platform Dev

            totalAntiBotFeesCollected += antiBotFee;

            // Direct routing (clean on-chain flows, no intermediary transfers)
            _safeSend(airdropTreasury, leaderboardFee);
            _safeSend(platformDevelopmentWallet, platformDevFee);

            emit AntiBotFeePaid(msg.sender, antiBotFee, elapsed);
            emit AntiBotFeeSplit(leaderboardFee, platformDevFee); // Transparency event
        }

        // AUDIT FIX: Step 2 - Calculate platform/creator fees from REMAINING value
        uint256 platformFee = remainingValue * 90 / 10000; // 0.9% of remainder
        uint256 creatorFee = remainingValue * 10 / 10000;  // 0.1% of remainder
        uint256 totalFees = platformFee + creatorFee;
        uint256 tradeAmount = remainingValue - totalFees;

        // Step 3: AMM calculation
        uint256 tokensOut = quoteBuy(tradeAmount);
        require(tokensOut >= minTokensOut, "Slippage too high");
        require(tokensOut > 0, "Insufficient output");

        // Step 4: Update state (CEI pattern)
        virtualKasReserve += tradeAmount;
        virtualTokenReserve -= tokensOut;

        accumulatedPlatformFees += platformFee;
        accumulatedCreatorFees += creatorFee;

        // Step 5: Transfer tokens (wallet cap enforced in _update override)
        _transfer(address(this), msg.sender, tokensOut);

        emit TokensPurchased(msg.sender, tokensOut, tradeAmount, platformFee, creatorFee, antiBotFee);

        // Note: Graduation checked by backend oracle off-chain
        // Backend monitors: if (virtualKasReserve * kasPrice >= $70K) → calls initiateGraduation()
    }

    // AUDIT FIX: Safe send helper (replaces .transfer)
    function _safeSend(address to, uint256 amount) private {
        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "Transfer failed");
    }

    function sellTokens(uint256 tokenAmount, uint256 minKasOut, uint256 deadline) external nonReentrant {
        require(!graduated && !graduating, "Token graduated or graduating");
        require(block.timestamp <= deadline, "Transaction expired");
        require(balanceOf(msg.sender) >= tokenAmount, "Insufficient balance");

        // Calculate FULL KAS output first (before fees)
        uint256 kasGross = quoteSell(tokenAmount);

        // Fee on KAS OUTPUT (1% of KAS) - NOT on tokens
        uint256 totalFeesKas = kasGross * TOTAL_FEE_BPS / 10000; // 1% of KAS
        uint256 creatorFeeKas = totalFeesKas * 10 / 100; // 10% of fees = 0.1% of KAS
        uint256 platformFeeKas = totalFeesKas - creatorFeeKas; // 90% of fees = 0.9% of KAS
        uint256 kasNet = kasGross - totalFeesKas;

        // Slippage check on NET amount user receives
        require(kasNet >= minKasOut, "Slippage too high");
        require(kasNet >= MIN_TRADE_AMOUNT, "Below minimum trade");

        // CEI Pattern: Update reserves FIRST (full KAS amount leaves)
        virtualTokenReserve += tokenAmount;
        virtualKasReserve -= kasGross; // Full amount (including fees)

        // Accumulate KAS fees (actual KAS, not hypothetical)
        accumulatedPlatformFees += platformFeeKas;
        accumulatedCreatorFees += creatorFeeKas;

        // Transfer tokens to pool
        _transfer(msg.sender, address(this), tokenAmount);

        // Send NET KAS to user (fees stay in contract balance)
        _safeSend(msg.sender, kasNet);

        emit TokensSold(msg.sender, tokenAmount, kasGross, platformFeeKas, creatorFeeKas);
    }

    function quoteBuy(uint256 kasIn) public view returns (uint256 tokensOut) {
        // Use ONLY virtual reserves for pricing (excludes accumulated fees)
        uint256 k = virtualTokenReserve * virtualKasReserve;

        // Constant product: (virtualTokenReserve - tokensOut) * (virtualKasReserve + kasIn) = k
        uint256 newKasReserve = virtualKasReserve + kasIn;

        // Prevent overflow and unreasonably large inputs that would drain the pool
        require(newKasReserve > virtualKasReserve, "Invalid input");
        require(kasIn <= virtualKasReserve * 1000000, "Invalid output");

        uint256 newTokenReserve = k / newKasReserve;
        tokensOut = virtualTokenReserve - newTokenReserve;

        // Basic output validation - ensures positive output
        require(tokensOut > 0 && tokensOut < virtualTokenReserve, "Invalid output");
    }

    function quoteSell(uint256 tokensIn) public view returns (uint256 kasOut) {
        uint256 k = virtualTokenReserve * virtualKasReserve;

        uint256 newTokenReserve = virtualTokenReserve + tokensIn;
        uint256 newKasReserve = k / newTokenReserve;
        kasOut = virtualKasReserve - newKasReserve;

        require(kasOut > 0 && kasOut < virtualKasReserve, "Invalid output");
    }

    // Get current anti-bot fee for a given KAS amount
    function getCurrentAntiBotFee(uint256 kasAmount) public view returns (uint256) {
        if (!antiBotEnabled) return 0;
        if (block.timestamp >= deploymentTime + 60) return 0;

        uint256 elapsed = block.timestamp - deploymentTime;
        uint256 feePercent = 9500 - (9400 * elapsed / 60);

        // Overflow protection
        if (kasAmount > type(uint256).max / feePercent) {
            return type(uint256).max;
        }

        return kasAmount * feePercent / 10000;
    }

    // Get seconds remaining until normal fees
    function getSecondsUntilNormalFees() public view returns (uint256) {
        if (!antiBotEnabled) return 0;
        if (block.timestamp >= deploymentTime + 60) return 0;
        return deploymentTime + 60 - block.timestamp;
    }

    // Get complete fee breakdown for UX
    function getEffectiveFeeBreakdown(uint256 kasAmount) external view returns (
        uint256 antiBotFee,
        uint256 platformFee,
        uint256 creatorFee,
        uint256 tradeAmount
    ) {
        antiBotFee = getCurrentAntiBotFee(kasAmount);
        uint256 remaining = kasAmount - antiBotFee;
        platformFee = remaining * 90 / 10000;
        creatorFee = remaining * 10 / 10000;
        tradeAmount = remaining - platformFee - creatorFee;
    }

    // Internal version for gas efficiency (M-2 Fix)
    function _getEffectiveFeeBreakdownInternal(uint256 kasAmount) internal view returns (
        uint256 antiBotFee,
        uint256 platformFee,
        uint256 creatorFee,
        uint256 tradeAmount
    ) {
        antiBotFee = getCurrentAntiBotFee(kasAmount);
        uint256 remaining = kasAmount - antiBotFee;
        platformFee = remaining * 90 / 10000;
        creatorFee = remaining * 10 / 10000;
        tradeAmount = remaining - platformFee - creatorFee;
    }

    function calculateOptimalSlippage(uint256 kasAmount) public view returns (uint256 optimalSlippageBps) {
        require(!graduated, "Use DEX slippage calculation post-graduation");

        // Base slippage for bonding curve (deterministic pricing)
        uint256 baseSlippage = 50; // 0.5% base

        // AUDIT FIX: Add zero check and overflow protection
        if (virtualKasReserve > 0) {
            uint256 tradeImpactBps = (kasAmount * 10000) / virtualKasReserve;

            // Cap trade impact at reasonable level (prevent overflow)
            if (tradeImpactBps > 10000) {
                tradeImpactBps = 10000; // Cap at 100% of pool
            }

            // Adjust slippage based on trade size
            if (tradeImpactBps > 100) { // Trade is >1% of pool
                baseSlippage += 50; // Increase to 1%
            }
        }

        // Anti-bot period adds volatility (more retry risk)
        if (antiBotEnabled && block.timestamp < deploymentTime + 60) {
            baseSlippage += 50; // +0.5% during anti-bot period
        }

        // Cap at 200 bps (2%) for bonding curve
        optimalSlippageBps = baseSlippage > 200 ? 200 : baseSlippage;
    }

    function getMinTokensOutWithAutoSlippage(uint256 kasIn) external view returns (uint256 minTokensOut) {
        require(!graduated, "Token graduated, use DEX");

        // M-2 FIX: Use internal version for gas efficiency
        (uint256 antiBotFee, uint256 platformFee, uint256 creatorFee, uint256 tradeAmount) 
            = _getEffectiveFeeBreakdownInternal(kasIn);

        uint256 expectedTokens = quoteBuy(tradeAmount);

        // Apply auto-calculated slippage
        uint256 slippageBps = calculateOptimalSlippage(kasIn);
        minTokensOut = expectedTokens * (10000 - slippageBps) / 10000;
    }

    function getSlippageRiskLevel(uint256 kasAmount) external view returns (uint8 riskLevel) {
        require(!graduated, "Token graduated");

        uint256 slippageBps = calculateOptimalSlippage(kasAmount);

        if (slippageBps < 200) return 0;      // <2% = Silent execution
        if (slippageBps < 500) return 1;      // 2-5% = Warning modal
        return 2;                              // >5% = Block trade (shouldn't happen on bonding curve)
    }

    function distributeFees() external nonReentrant {
        require(msg.sender == treasury || msg.sender == admin, "Unauthorized");

        uint256 platformFeesToDistribute = accumulatedPlatformFees;
        require(platformFeesToDistribute > 0, "No fees to distribute");

        // Reset accumulated fees FIRST (CEI pattern)
        accumulatedPlatformFees = 0;

        // Calculate shares from ONLY platform fees
        uint256 devAmount = platformFeesToDistribute * 40 / 100;      // 40%
        uint256 buybackAmount = platformFeesToDistribute * 30 / 100;  // 30%
        uint256 kaspaAmount = platformFeesToDistribute * 15 / 100;    // 15%
        uint256 communityAmount = platformFeesToDistribute - devAmount - buybackAmount - kaspaAmount; // 15%

        // Send to designated wallets
        _safeSend(platformDevelopmentWallet, devAmount);
        _safeSend(buybackReserveWallet, buybackAmount);
        _safeSend(kaspaNetworkSupportWallet, kaspaAmount);
        _safeSend(communityRewardsWallet, communityAmount);

        emit FeesDistributed(devAmount, buybackAmount, kaspaAmount, communityAmount);
    }

    // Called by backend oracle when USD market cap reaches $70,000
    function initiateGraduation() external nonReentrant {
        require(msg.sender == graduationOracle, "Only oracle can initiate");
        require(!graduated && !graduating, "Already graduated or graduating");
        require(graduationController != address(0), "GraduationController not set");

        // Verify sufficient balance for DEX liquidity
        // Note: Subtract initial virtual seed since it was never actual KAS
        uint256 kasBalance = address(this).balance;
        uint256 requiredKas = (virtualKasReserve - INITIAL_VIRTUAL_KAS) + accumulatedPlatformFees + accumulatedCreatorFees;
        require(kasBalance >= requiredKas, "Insufficient KAS balance");

        graduating = true; // Lock trading during graduation

        // Calculate liquidity: virtualKasReserve + 25% token supply
        uint256 lpTokens = totalSupply() * LP_SUPPLY_PCT / 100; // 25%

        // V10 FIX: Transfer tokens directly to GC (no approve/transferFrom - avoids STF error)
        // Use same pattern as KAS transfer - pool PUSHES liquidity instead of GC PULLING it
        _transfer(address(this), graduationController, lpTokens);

        // Transfer actual KAS liquidity to GraduationController (excluding virtual seed)
        // FIXED: Send to GraduationController, not oracle wallet
        require(virtualKasReserve >= INITIAL_VIRTUAL_KAS, "Invalid reserve state");
        uint256 actualKasLiquidity = virtualKasReserve - INITIAL_VIRTUAL_KAS;
        _safeSend(graduationController, actualKasLiquidity);
        liquidityTransferred = true; // Mark KAS as transferred - prevents cancellation after this point

        emit GraduationInitiated(virtualKasReserve, lpTokens);

        // CRITICAL FIX: Pool calls GraduationController directly so msg.sender = pool address
        // This ensures GC captures correct snapshot with poolContract = address(this)
        IGraduationController(graduationController).initiateGraduation(address(this));
    }

    // Completes graduation after DEX liquidity added
    // V2 FIX: Only GraduationController can call this (prevents oracle bypass attack)
    function completeGraduation() external nonReentrant {
        require(msg.sender == graduationController, "Only GraduationController");
        require(graduating, "Graduation not initiated");

        graduating = false;
        graduated = true;

        // Burn unsold curve tokens (any tokens left in contract beyond LP reserve)
        uint256 lpReserve = totalSupply() * LP_SUPPLY_PCT / 100;
        uint256 contractBalance = balanceOf(address(this));
        if (contractBalance > lpReserve) {
            uint256 burnAmount = contractBalance - lpReserve;
            _burn(address(this), burnAmount);
            emit UnsoldTokensBurned(burnAmount);
        }

        emit Graduated(address(this), virtualKasReserve, lpReserve);
        emit GraduationCompleted(address(this), virtualKasReserve, lpReserve);

        // Reset liquidity transfer flag after successful graduation
        liquidityTransferred = false;
    }

    // Cancel graduation (only oracle or owner)
    function cancelGraduation() external nonReentrant {
        require(msg.sender == graduationOracle || msg.sender == owner(), "Unauthorized");
        require(graduating && !graduated, "Cannot cancel");
        require(!liquidityTransferred, "Cannot cancel after KAS transfer");
        graduating = false;
        emit GraduationCancelled(address(this));
    }

    // V2 RECOVERY: Force reset corrupted graduation state (owner-only emergency function)
    // Use case: When graduation was marked complete without LP creation
    function forceResetGraduation() external onlyOwner {
        require(graduated, "Not in graduated state");
        require(graduationController != address(0), "GC not set");

        // Reset all graduation flags to allow re-initiation
        graduating = false;
        graduated = false;
        liquidityTransferred = false;

        emit GraduationCancelled(address(this));
    }

    // Creator claims accumulated fees
    function withdrawCreatorFees() external nonReentrant {
        require(msg.sender == creator, "Only creator can withdraw");
        require(accumulatedCreatorFees > 0, "No fees to withdraw");

        uint256 amount = accumulatedCreatorFees;
        accumulatedCreatorFees = 0; // Reset before transfer (CEI)

        _safeSend(creator, amount);

        emit CreatorFeesWithdrawn(creator, amount);
    }

    // View function for creator to check claimable amount
    function getCreatorClaimableAmount() external view returns (uint256) {
        return accumulatedCreatorFees;
    }

    // Creator distributes reserve tokens (one-time only, for team/marketing/airdrops)
    function distributeReserve(address[] calldata recipients, uint256[] calldata amounts) external nonReentrant {
        require(msg.sender == creator, "Only creator can distribute");
        require(reservedPercentage == 0, "PRO tokens use vesting contracts");
        require(!reserveDistributed, "Reserve already distributed");
        require(!graduated && !graduating, "Cannot distribute after graduation");
        require(recipients.length == amounts.length, "Length mismatch");
        require(recipients.length > 0, "Empty recipients");

        // Calculate total distribution amount
        uint256 totalDistribution = 0;
        for (uint256 i = 0; i < amounts.length; i++) {
            require(recipients[i] != address(0), "Invalid recipient");
            require(amounts[i] > 0, "Invalid amount");
            totalDistribution += amounts[i];
        }

        // Available reserve = contract balance - virtual token reserve
        uint256 availableReserve = balanceOf(address(this)) - virtualTokenReserve;
        require(totalDistribution <= availableReserve, "Exceeds available reserve");

        // Mark as distributed before transfers (CEI pattern)
        reserveDistributed = true;

        // Transfer tokens to recipients
        for (uint256 i = 0; i < recipients.length; i++) {
            _transfer(address(this), recipients[i], amounts[i]);
        }

        emit ReserveDistributed(creator, recipients, amounts, totalDistribution);
    }

    // View function to check reserve distribution status
    function getReserveStatus() external view returns (
        bool distributed,
        uint256 availableReserve,
        uint256 totalReserve
    ) {
        // H-2 FIX: PRO tokens use vesting contracts, not reserve distribution
        require(reservedPercentage == 0, "PRO tokens use vesting contracts");

        distributed = reserveDistributed;
        totalReserve = totalSupply() * LP_SUPPLY_PCT / 100; // 25% of total supply

        // Available reserve = contract balance - virtual token reserve
        if (!graduated && !graduating) {
            availableReserve = balanceOf(address(this)) - virtualTokenReserve;
        } else {
            availableReserve = 0; // No reserve available after graduation starts
        }
    }

    // M-4 Fix: Prevent direct KAS transfers (force use of buyTokens)
    receive() external payable {
        revert("Use buyTokens() to purchase");
    }

    // Emergency pause (only admin)
    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // Update graduation oracle (only admin)
    // FIX #10: Prevent oracle changes during graduation (race condition protection)
    function setGraduationOracle(address newOracle) external onlyOwner {
        require(!graduating, "Cannot change oracle during graduation");
        require(newOracle != address(0), "Invalid oracle");
        graduationOracle = newOracle;
        emit GraduationOracleUpdated(newOracle);
    }

    // Set graduation controller contract address (only admin)
    function setGraduationController(address newController) external onlyOwner {
        require(!graduating, "Cannot change controller during graduation");
        require(newController != address(0), "Invalid controller");
        graduationController = newController;
    }

    // Override _update to enforce 10% wallet cap (OpenZeppelin v5)
    function _update(address from, address to, uint256 amount) internal virtual override {
        // Enforce wallet cap with exemptions for:
        // 1. Contract itself (holds curve + LP supply)
        // 2. Airdrop treasury (holds vested allocations up to 25%)
        // 3. Graduation oracle (receives LP tokens for DEX)
        // 4. Graduation controller (receives 25% LP supply for DEX)
        // 5. Owner (emergency operations and administrative actions)
        // 6. Vesting contracts (can hold up to 25%)
        // 7. Transfers FROM airdropTreasury (allows >10% vesting distributions to team/founders)
        // 8. Transfers FROM contract (buy operations bypass cap due to bonding curve pricing)
        // 9. Graduated pools (no restrictions after DEX listing)
        if (to != address(0) &&
            to != address(this) && 
            to != airdropTreasury && 
            to != graduationOracle &&
            to != graduationController &&
            to != owner() &&
            !isVestingContract[to] &&
            !isVestingContract[from] &&
            from != airdropTreasury &&
            from != address(this) &&
            !graduated) {
            uint256 recipientBalance = balanceOf(to);
            uint256 maxWallet = totalSupply() * MAX_WALLET_PCT / 100; // 10%
            require(recipientBalance + amount <= maxWallet, "Exceeds max wallet");
        }

        super._update(from, to, amount);
    }
}

contracts/CliffVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract CliffVesting is ReentrancyGuard {
    IERC20 public immutable token;
    address public immutable beneficiary;
    uint256 public immutable totalAllocation;
    uint256 public immutable startTime;
    uint256 public immutable cliff;
    uint256 public immutable vestingEnd;
    uint256 public withdrawn;

    event TokensWithdrawn(address indexed beneficiary, uint256 amount);

    constructor(
        address _token,
        address _beneficiary,
        uint256 _totalAllocation,
        uint256 _cliffMonths,      // 6 for team
        uint256 _vestingMonths     // 18 for team (after cliff)
    ) {
        require(_token != address(0), "Invalid token");
        require(_beneficiary != address(0), "Invalid beneficiary");
        require(_totalAllocation > 0, "Invalid allocation");
        require(_cliffMonths > 0, "Invalid cliff");
        require(_vestingMonths > 0, "Invalid vesting period");

        token = IERC20(_token);
        beneficiary = _beneficiary;
        totalAllocation = _totalAllocation;
        startTime = block.timestamp;
        cliff = _cliffMonths * 30 days;
        vestingEnd = startTime + (_cliffMonths + _vestingMonths) * 30 days;
    }

    function getUnlockedAmount() public view returns (uint256) {
        if (block.timestamp < startTime + cliff) {
            return 0; // Nothing unlocked before cliff
        }

        if (block.timestamp >= vestingEnd) {
            return totalAllocation; // 100% unlocked after full vesting
        }

        uint256 vestingDuration = vestingEnd - (startTime + cliff);
        uint256 elapsedSinceCliff = block.timestamp - (startTime + cliff);

        return (totalAllocation * elapsedSinceCliff) / vestingDuration;
    }

    function getWithdrawableAmount() public view returns (uint256) {
        uint256 unlocked = getUnlockedAmount();
        return unlocked > withdrawn ? unlocked - withdrawn : 0;
    }

    function withdraw() external nonReentrant {
        require(msg.sender == beneficiary, "Only beneficiary can withdraw");

        uint256 withdrawable = getWithdrawableAmount();
        require(withdrawable > 0, "No tokens available");

        withdrawn += withdrawable;

        require(token.transfer(beneficiary, withdrawable), "Transfer failed");
        emit TokensWithdrawn(beneficiary, withdrawable);
    }
}

contracts/GraduationController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./BondingCurvePool.sol";

// Kaspa Finance interfaces (Uniswap V3 architecture)
interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    function mint(MintParams calldata params) external payable returns (
        uint256 tokenId,
        uint128 liquidity,
        uint256 amount0,
        uint256 amount1
    );
}

interface IWKAS {
    function deposit() external payable;
    function approve(address spender, uint256 amount) external returns (bool);
}

contract GraduationController is Ownable, ReentrancyGuard {
    // Kaspa Finance integration
    address public immutable kaspaFinancePositionManager;
    address public immutable kaspaFinanceWKAS;

    // Oracle for USD price checks (backend service)
    address public graduationOracle;

    // Graduation tracking
    mapping(address => bool) public hasGraduated;
    mapping(address => uint256) public graduationTimestamp;
    mapping(address => uint256) public liquidityPositionId; // Uniswap V3 NFT position ID

    // Constants
    uint24 public constant POOL_FEE_TIER = 2500; // 0.25% fee tier
    int24 public constant FULL_RANGE_TICK_LOWER = -887220; // Full range position
    int24 public constant FULL_RANGE_TICK_UPPER = 887220;

    // M-5 FIX: Configurable graduation parameters
    uint256 public graduationSlippageBps = 500; // 5% default
    uint256 public graduationDeadlineSeconds = 300; // 5 minutes default

    // Events
    event GraduationInitiated(
        address indexed tokenAddress,
        uint256 kasLiquidity,
        uint256 tokenLiquidity,
        uint256 timestamp
    );

    event GraduationCompleted(
        address indexed tokenAddress,
        uint256 liquidityPositionId,
        uint256 kasAdded,
        uint256 tokensAdded,
        uint256 timestamp
    );

    event GraduationFailed(
        address indexed tokenAddress,
        string reason,
        uint256 timestamp
    );

    event OracleUpdated(address indexed newOracle);
    event GraduationParamsUpdated(uint256 slippageBps, uint256 deadlineSeconds);

    constructor(
        address _kaspaFinancePositionManager,
        address _kaspaFinanceWKAS,
        address _graduationOracle
    ) Ownable(msg.sender) {
        require(_kaspaFinancePositionManager != address(0), "Invalid position manager");
        require(_kaspaFinanceWKAS != address(0), "Invalid WKAS");
        require(_graduationOracle != address(0), "Invalid oracle");

        // L-2 FIX: Duplicate address validation
        require(_kaspaFinancePositionManager != _kaspaFinanceWKAS, "Duplicate addresses");
        require(_graduationOracle != msg.sender, "Oracle cannot be owner");

        kaspaFinancePositionManager = _kaspaFinancePositionManager;
        kaspaFinanceWKAS = _kaspaFinanceWKAS;
        graduationOracle = _graduationOracle;
    }

    // Allow contract to receive KAS for graduation liquidity
    receive() external payable {}

    // Step 1: Initiate graduation (called by backend oracle when USD threshold reached)
    function initiateGraduation(address tokenAddress) external nonReentrant {
        require(msg.sender == graduationOracle, "Only oracle can initiate");
        require(!hasGraduated[tokenAddress], "Already graduated");

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));

        // Trigger graduation on the pool contract
        try pool.initiateGraduation() {
            emit GraduationInitiated(
                tokenAddress,
                pool.virtualKasReserve(),
                pool.totalSupply() * 25 / 100, // 25% LP supply
                block.timestamp
            );
        } catch Error(string memory reason) {
            emit GraduationFailed(tokenAddress, reason, block.timestamp);
            revert(reason);
        }
    }

    // Step 2: Complete graduation (add liquidity to Kaspa Finance DEX)
    function completeGraduation(address tokenAddress) external nonReentrant {
        require(msg.sender == graduationOracle, "Only oracle can complete");
        require(!hasGraduated[tokenAddress], "Already graduated");

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));
        require(pool.graduating(), "Graduation not initiated");

        // Get liquidity amounts (KAS was already transferred during initiation)
        uint256 kasLiquidity = address(this).balance; // Use actual KAS balance controller has
        require(kasLiquidity > 0, "No KAS received");

        uint256 tokenLiquidity = pool.totalSupply() * 25 / 100; // 25% of total supply

        // Transfer tokens from pool to this contract
        uint256 allowance = IERC20(tokenAddress).allowance(address(pool), address(this));
        require(allowance >= tokenLiquidity, "Insufficient approval");

        IERC20(tokenAddress).transferFrom(address(pool), address(this), tokenLiquidity);

        // Wrap KAS to WKAS for Uniswap V3 pool
        IWKAS wkas = IWKAS(kaspaFinanceWKAS);
        wkas.deposit{value: kasLiquidity}();

        // Approve position manager to spend tokens
        IERC20(tokenAddress).approve(kaspaFinancePositionManager, tokenLiquidity);
        wkas.approve(kaspaFinancePositionManager, kasLiquidity);

        // Determine token ordering (token0 < token1)
        (address token0, address token1) = tokenAddress < kaspaFinanceWKAS
            ? (tokenAddress, kaspaFinanceWKAS)
            : (kaspaFinanceWKAS, tokenAddress);

        (uint256 amount0, uint256 amount1) = tokenAddress < kaspaFinanceWKAS
            ? (tokenLiquidity, kasLiquidity)
            : (kasLiquidity, tokenLiquidity);

        // Create full-range liquidity position on Kaspa Finance (Uniswap V3)
        INonfungiblePositionManager.MintParams memory params = INonfungiblePositionManager.MintParams({
            token0: token0,
            token1: token1,
            fee: POOL_FEE_TIER, // 0.25% fee tier
            tickLower: FULL_RANGE_TICK_LOWER,
            tickUpper: FULL_RANGE_TICK_UPPER,
            amount0Desired: amount0,
            amount1Desired: amount1,
            amount0Min: amount0 * (10000 - graduationSlippageBps) / 10000,
            amount1Min: amount1 * (10000 - graduationSlippageBps) / 10000,
            recipient: address(this), // Controller holds the LP NFT
            deadline: block.timestamp + graduationDeadlineSeconds
        });

        (uint256 positionId, , uint256 actualAmount0, uint256 actualAmount1) = 
            INonfungiblePositionManager(kaspaFinancePositionManager).mint(params);

        // Mark as graduated
        hasGraduated[tokenAddress] = true;
        graduationTimestamp[tokenAddress] = block.timestamp;
        liquidityPositionId[tokenAddress] = positionId;

        // Complete graduation on pool contract (locks trading, burns unsold tokens)
        pool.completeGraduation();

        emit GraduationCompleted(
            tokenAddress,
            positionId,
            tokenAddress < kaspaFinanceWKAS ? actualAmount1 : actualAmount0, // KAS amount
            tokenAddress < kaspaFinanceWKAS ? actualAmount0 : actualAmount1, // Token amount
            block.timestamp
        );
    }

    // Update graduation oracle
    function setGraduationOracle(address newOracle) external onlyOwner {
        require(newOracle != address(0), "Invalid oracle");
        graduationOracle = newOracle;
        emit OracleUpdated(newOracle);
    }

    // M-5 FIX: Set graduation parameters
    function setGraduationParams(uint256 _slippageBps, uint256 _deadlineSeconds) external onlyOwner {
        require(_slippageBps <= 1000, "Max 10% slippage");
        require(_deadlineSeconds >= 60, "Min 1 minute");
        graduationSlippageBps = _slippageBps;
        graduationDeadlineSeconds = _deadlineSeconds;
        emit GraduationParamsUpdated(_slippageBps, _deadlineSeconds);
    }

    // Emergency: Reverse failed graduation (only if DEX liquidity not added)
    function emergencyReverseGraduation(address tokenAddress) external onlyOwner {
        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));
        require(pool.graduating(), "Not graduating");
        require(!hasGraduated[tokenAddress], "Already graduated");

        // This would need a special function in BondingCurvePool to reverse graduation
        // For now, this is a placeholder for emergency controls

        emit GraduationFailed(tokenAddress, "Emergency reversal by admin", block.timestamp);
    }

    // Withdraw accidentally sent tokens (emergency recovery)
    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner(), amount);
    }

    // Check if token has graduated
    function isGraduated(address tokenAddress) external view returns (bool) {
        return hasGraduated[tokenAddress];
    }

    // Get graduation info
    function getGraduationInfo(address tokenAddress) external view returns (
        bool graduated,
        uint256 timestamp,
        uint256 positionId
    ) {
        return (
            hasGraduated[tokenAddress],
            graduationTimestamp[tokenAddress],
            liquidityPositionId[tokenAddress]
        );
    }
}

contracts/GraduationControllerV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title GraduationController V2
 * @notice Manages token graduation from bonding curve to Uniswap V3 DEX liquidity
 * @dev Complete rewrite fixing all critical issues from V1:
 *      - Added Uniswap V3 pool creation
 *      - Added pool price initialization
 *      - Fixed token transfer logic
 *      - Added comprehensive validation
 *      - Added security protections
 * 
 * Version: 2.0.0
 * Deployment Date: October 23, 2025
 * Kaspa Finance Integration
 */

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./BondingCurvePool.sol";

/**
 * @title FullMath Library
 * @notice Safe 512-bit multiplication and division from Uniswap V3
 * @dev Prevents overflow when calculating sqrtPriceX96 with large reserves
 */
library FullMath {
    /**
     * @notice Calculates floor(a×b÷denominator) with full precision
     * @dev Handles intermediate overflow by using 512-bit math
     * @param a The multiplicand
     * @param b The multiplier
     * @param denominator The divisor
     * @return result The result as a uint256
     */
    function mulDiv(
        uint256 a,
        uint256 b,
        uint256 denominator
    ) internal pure returns (uint256 result) {
        // 512-bit multiply [prod1 prod0] = a * b
        // Compute the product mod 2**256 and mod 2**256 - 1
        // then use the Chinese Remainder Theorem to reconstruct
        uint256 prod0; // Least significant 256 bits of the product
        uint256 prod1; // Most significant 256 bits of the product
        assembly {
            let mm := mulmod(a, b, not(0))
            prod0 := mul(a, b)
            prod1 := sub(sub(mm, prod0), lt(mm, prod0))
        }

        // Handle non-overflow cases, 256 by 256 division
        if (prod1 == 0) {
            require(denominator > 0);
            assembly {
                result := div(prod0, denominator)
            }
            return result;
        }

        // Make sure the result is less than 2**256
        // Also prevents denominator == 0
        require(denominator > prod1);

        ///////////////////////////////////////////////
        // 512 by 256 division.
        ///////////////////////////////////////////////

        // Make division exact by subtracting the remainder from [prod1 prod0]
        // Compute remainder using mulmod
        uint256 remainder;
        assembly {
            remainder := mulmod(a, b, denominator)
        }
        // Subtract 256 bit number from 512 bit number
        assembly {
            prod1 := sub(prod1, gt(remainder, prod0))
            prod0 := sub(prod0, remainder)
        }

        // Factor powers of two out of denominator
        // Compute largest power of two divisor of denominator.
        // Always >= 1.
        uint256 twos = denominator & (~denominator + 1);
        // Divide denominator by power of two
        assembly {
            denominator := div(denominator, twos)
        }

        // Divide [prod1 prod0] by the factors of two
        assembly {
            prod0 := div(prod0, twos)
        }
        // Shift in bits from prod1 into prod0. For this we need
        // to flip `twos` such that it is 2**256 / twos.
        // If twos is zero, then it becomes one
        assembly {
            twos := add(div(sub(0, twos), twos), 1)
        }
        // CRITICAL: This multiplication can overflow in 256-bit arithmetic but is correct mod 2^256
        unchecked {
            prod0 |= prod1 * twos;
        }

        // Invert denominator mod 2**256
        // Now that denominator is an odd number, it has an inverse
        // modulo 2**256 such that denominator * inv = 1 mod 2**256.
        // Compute the inverse by starting with a seed that is correct
        // correct for four bits. That is, denominator * inv = 1 mod 2**4
        uint256 inv = (3 * denominator) ^ 2;
        // Now use Newton-Raphson iteration to improve the precision.
        // Thanks to Hensel's lifting lemma, this also works in modular
        // arithmetic, doubling the correct bits in each step.
        // CRITICAL: Use unchecked blocks - modular arithmetic is SUPPOSED to overflow
        unchecked {
            inv *= 2 - denominator * inv; // inverse mod 2**8
            inv *= 2 - denominator * inv; // inverse mod 2**16
            inv *= 2 - denominator * inv; // inverse mod 2**32
            inv *= 2 - denominator * inv; // inverse mod 2**64
            inv *= 2 - denominator * inv; // inverse mod 2**128
            inv *= 2 - denominator * inv; // inverse mod 2**256
        }

        // Because the division is now exact we can divide by multiplying
        // with the modular inverse of denominator. This will give us the
        // correct result modulo 2**256. Since the preconditions guarantee
        // that the outcome is less than 2**256, this is the final result.
        // We don't need to compute the high bits of the result and prod1
        // is no longer required.
        // CRITICAL: Final multiplication must be unchecked as it uses modular arithmetic
        unchecked {
            result = prod0 * inv;
        }
        return result;
    }
}

/**
 * @title Uniswap V3 Factory Interface
 * @notice Interface for creating and querying Uniswap V3 pools
 */
interface IUniswapV3Factory {
    /**
     * @notice Creates a new Uniswap V3 pool for the given token pair and fee tier
     * @param tokenA First token address
     * @param tokenB Second token address
     * @param fee Fee tier (500 = 0.05%, 2500 = 0.25%, 3000 = 0.30%, 10000 = 1%)
     * @return pool Address of the created pool
     */
    function createPool(address tokenA, address tokenB, uint24 fee) 
        external returns (address pool);

    /**
     * @notice Returns the pool address for a given token pair and fee tier
     * @param tokenA First token address
     * @param tokenB Second token address
     * @param fee Fee tier
     * @return pool Address of the pool (address(0) if doesn't exist)
     */
    function getPool(address tokenA, address tokenB, uint24 fee) 
        external view returns (address pool);
}

/**
 * @title Uniswap V3 Pool Interface
 * @notice Interface for initializing and querying Uniswap V3 pool state
 */
interface IUniswapV3Pool {
    /**
     * @notice Initialize the pool with a starting price
     * @dev Can only be called once. Must be called before any liquidity operations
     * @param sqrtPriceX96 The initial sqrt price of the pool as a Q64.96 value
     */
    function initialize(uint160 sqrtPriceX96) external;

    /**
     * @notice Returns the current state of the pool
     * @return sqrtPriceX96 The current price of the pool as a sqrt(token1/token0) Q64.96 value
     * @return tick The current tick of the pool
     * @return observationIndex The index of the last oracle observation
     * @return observationCardinality The current maximum number of observations stored
     * @return observationCardinalityNext The next maximum number of observations to store
     * @return feeProtocol The protocol fee for both tokens of the pool
     * @return unlocked Whether the pool is currently locked to reentrancy
     */
    function slot0() external view returns (
        uint160 sqrtPriceX96,
        int24 tick,
        uint16 observationIndex,
        uint16 observationCardinality,
        uint16 observationCardinalityNext,
        uint8 feeProtocol,
        bool unlocked
    );

    /**
     * @notice Returns the first token of the pool (lower address)
     */
    function token0() external view returns (address);

    /**
     * @notice Returns the second token of the pool (higher address)
     */
    function token1() external view returns (address);
}

/**
 * @title Uniswap V3 NFT Position Manager Interface
 * @notice Interface for managing Uniswap V3 liquidity positions as NFTs
 */
interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    struct CollectParams {
        uint256 tokenId;
        address recipient;
        uint128 amount0Max;
        uint128 amount1Max;
    }

    /**
     * @notice Mint a new liquidity position NFT
     * @param params Parameters for minting the position
     * @return tokenId The ID of the newly minted NFT
     * @return liquidity The amount of liquidity minted
     * @return amount0 The amount of token0 added
     * @return amount1 The amount of token1 added
     */
    function mint(MintParams calldata params) external payable returns (
        uint256 tokenId,
        uint128 liquidity,
        uint256 amount0,
        uint256 amount1
    );

    /**
     * @notice Collect fees from a position
     * @param params Parameters for collecting fees
     * @return amount0 The amount of token0 fees collected
     * @return amount1 The amount of token1 fees collected
     */
    function collect(CollectParams calldata params) external payable returns (
        uint256 amount0,
        uint256 amount1
    );
}

/**
 * @title Wrapped KAS Interface
 * @notice Interface for wrapping and unwrapping KAS
 */
interface IWKAS {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title GraduationController V2
 * @notice Main graduation controller with complete Uniswap V3 integration
 */
contract GraduationController is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============ State Variables ============

    /// @notice Contract version for tracking deployments
    string public constant VERSION = "2.0.0";

    /// @notice Kaspa Finance Uniswap V3 factory address
    address public immutable kaspaFinanceFactory;

    /// @notice Kaspa Finance NFT Position Manager address
    address public immutable kaspaFinancePositionManager;

    /// @notice Wrapped KAS token address
    address public immutable kaspaFinanceWKAS;

    /// @notice Address authorized to trigger graduations (backend oracle)
    address public graduationOracle;

    /// @notice TokenFactory address for validating legitimate tokens
    address public tokenFactory;

    // Graduation tracking
    mapping(address => bool) public hasGraduated;
    mapping(address => uint256) public graduationTimestamp;
    mapping(address => uint256) public liquidityPositionId;
    mapping(address => address) public uniswapPoolAddress;

    // Expected liquidity amounts (stored during initiation)
    mapping(address => uint256) public expectedKasLiquidity;
    mapping(address => uint256) public expectedTokenLiquidity;

    // ============ Constants ============

    /// @notice Uniswap V3 pool fee tier (0.25%)
    uint24 public constant POOL_FEE_TIER = 2500;

    /// @notice Full range liquidity position tick bounds
    int24 public constant FULL_RANGE_TICK_LOWER = -887220;
    int24 public constant FULL_RANGE_TICK_UPPER = 887220;

    /// @notice Initial virtual KAS reserve in bonding curve
    uint256 public constant INITIAL_VIRTUAL_KAS = 1000 ether;

    /// @notice Percentage of token supply to add as liquidity (25%)
    uint256 public constant LP_SUPPLY_PERCENTAGE = 25;

    // ============ Configurable Parameters ============

    /// @notice Slippage tolerance for liquidity minting (in basis points, 500 = 5%)
    uint256 public graduationSlippageBps = 500;

    /// @notice Deadline for graduation transactions (in seconds)
    uint256 public graduationDeadlineSeconds = 300;

    /// @notice Maximum price deviation tolerance (in basis points, 100 = 1%)
    uint256 public maxPriceDeviationBps = 100;

    // ============ Events ============

    event GraduationInitiated(
        address indexed tokenAddress,
        uint256 expectedKasLiquidity,
        uint256 expectedTokenLiquidity,
        uint256 timestamp
    );

    event PoolCreated(
        address indexed tokenAddress,
        address indexed poolAddress,
        uint160 sqrtPriceX96,
        uint256 timestamp
    );

    event PoolInitialized(
        address indexed tokenAddress,
        address indexed poolAddress,
        uint160 sqrtPriceX96,
        uint256 timestamp
    );

    event GraduationCompleted(
        address indexed tokenAddress,
        address indexed poolAddress,
        uint256 liquidityPositionId,
        uint256 kasAdded,
        uint256 tokensAdded,
        uint256 timestamp
    );

    event GraduationCancelled(
        address indexed tokenAddress,
        uint256 kasReturned,
        uint256 tokensReturned,
        string reason,
        uint256 timestamp
    );

    event GraduationFailed(
        address indexed tokenAddress,
        string reason,
        uint256 timestamp
    );

    event FeesCollected(
        address indexed tokenAddress,
        uint256 amount0,
        uint256 amount1,
        uint256 timestamp
    );

    event OracleUpdated(address indexed oldOracle, address indexed newOracle);
    event TokenFactoryUpdated(address indexed oldFactory, address indexed newFactory);
    event GraduationParamsUpdated(uint256 slippageBps, uint256 deadlineSeconds, uint256 maxPriceDeviationBps);
    event EmergencyWithdrawal(address indexed token, uint256 amount, address indexed recipient);

    // ============ Errors ============

    error OnlyOracle();
    error OnlyValidToken();
    error AlreadyGraduated();
    error NotGraduating();
    error LiquidityNotTransferred();
    error InsufficientKAS();
    error InsufficientTokens();
    error InvalidPoolAddress();
    error InvalidPrice();
    error PriceDeviationTooHigh();
    error SlippageExceeded();
    error NoLiquidityMinted();
    error InvalidAddress();
    error InvalidParameters();
    error PoolCreationFailed();
    error PoolInitializationFailed();
    error TransferFailed();

    // ============ Constructor ============

    /**
     * @notice Initialize the GraduationController with Kaspa Finance addresses
     * @param _kaspaFinanceFactory Uniswap V3 factory address
     * @param _kaspaFinancePositionManager NFT Position Manager address
     * @param _kaspaFinanceWKAS Wrapped KAS token address
     * @param _graduationOracle Backend oracle address authorized to trigger graduations
     * @param _tokenFactory TokenFactory address for validating tokens
     */
    constructor(
        address _kaspaFinanceFactory,
        address _kaspaFinancePositionManager,
        address _kaspaFinanceWKAS,
        address _graduationOracle,
        address _tokenFactory
    ) Ownable(msg.sender) {
        if (_kaspaFinanceFactory == address(0)) revert InvalidAddress();
        if (_kaspaFinancePositionManager == address(0)) revert InvalidAddress();
        if (_kaspaFinanceWKAS == address(0)) revert InvalidAddress();
        if (_graduationOracle == address(0)) revert InvalidAddress();
        if (_tokenFactory == address(0)) revert InvalidAddress();

        // Validate no duplicate addresses
        require(
            _kaspaFinanceFactory != _kaspaFinancePositionManager &&
            _kaspaFinanceFactory != _kaspaFinanceWKAS &&
            _kaspaFinancePositionManager != _kaspaFinanceWKAS,
            "Duplicate addresses"
        );

        kaspaFinanceFactory = _kaspaFinanceFactory;
        kaspaFinancePositionManager = _kaspaFinancePositionManager;
        kaspaFinanceWKAS = _kaspaFinanceWKAS;
        graduationOracle = _graduationOracle;
        tokenFactory = _tokenFactory;
    }

    // ============ Modifiers ============

    /**
     * @notice Ensure caller is the authorized graduation oracle
     */
    modifier onlyOracle() {
        if (msg.sender != graduationOracle) revert OnlyOracle();
        _;
    }

    /**
     * @notice Ensure token address is a valid BondingCurvePool from our factory
     * @param tokenAddress The token address to validate
     */
    modifier onlyValidToken(address tokenAddress) {
        // This assumes TokenFactory has a mapping: mapping(address => bool) public isValidToken;
        // If not, we can use a try-catch pattern or maintain our own registry
        if (tokenFactory != address(0)) {
            (bool success, bytes memory data) = tokenFactory.staticcall(
                abi.encodeWithSignature("isValidToken(address)", tokenAddress)
            );
            if (success && data.length > 0) {
                bool isValid = abi.decode(data, (bool));
                if (!isValid) revert OnlyValidToken();
            }
        }
        _;
    }

    // ============ Receive Function ============

    /**
     * @notice Allow contract to receive KAS for graduation liquidity
     */
    receive() external payable {}

    // ============ Main Graduation Functions ============

    /**
     * @notice Step 1: Initiate graduation process
     * @dev Called by backend oracle when token reaches $50 market cap
     * @param tokenAddress Address of the BondingCurvePool token to graduate
     */
    function initiateGraduation(address tokenAddress) 
        external 
        nonReentrant 
        whenNotPaused
        onlyOracle 
        onlyValidToken(tokenAddress)
    {
        if (hasGraduated[tokenAddress]) revert AlreadyGraduated();

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));

        // Calculate expected liquidity amounts BEFORE initiating
        uint256 expectedKas = pool.virtualKasReserve() > INITIAL_VIRTUAL_KAS 
            ? pool.virtualKasReserve() - INITIAL_VIRTUAL_KAS 
            : 0;
        uint256 expectedTokens = (pool.totalSupply() * LP_SUPPLY_PERCENTAGE) / 100;

        if (expectedKas == 0 || expectedTokens == 0) revert InsufficientKAS();

        // Store expected amounts
        expectedKasLiquidity[tokenAddress] = expectedKas;
        expectedTokenLiquidity[tokenAddress] = expectedTokens;

        // Trigger graduation on the pool contract
        // This should transfer KAS to this contract and set graduating = true
        try pool.initiateGraduation() {
            emit GraduationInitiated(
                tokenAddress,
                expectedKas,
                expectedTokens,
                block.timestamp
            );
        } catch Error(string memory reason) {
            emit GraduationFailed(tokenAddress, reason, block.timestamp);
            revert(reason);
        } catch (bytes memory) {
            emit GraduationFailed(tokenAddress, "Unknown error in pool.initiateGraduation", block.timestamp);
            revert("Pool graduation initiation failed");
        }
    }

    /**
     * @notice Step 2: Complete graduation by creating Uniswap V3 pool and adding liquidity
     * @dev Called by backend oracle after initiation succeeds
     * @param tokenAddress Address of the BondingCurvePool token to graduate
     */
    function completeGraduation(address tokenAddress) 
        external 
        nonReentrant 
        whenNotPaused
        onlyOracle 
    {
        if (hasGraduated[tokenAddress]) revert AlreadyGraduated();

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));

        // Validate pool state
        if (!pool.graduating()) revert NotGraduating();
        if (!pool.liquidityTransferred()) revert LiquidityNotTransferred();

        // Get expected liquidity amounts
        uint256 kasLiquidity = expectedKasLiquidity[tokenAddress];
        uint256 tokenLiquidity = expectedTokenLiquidity[tokenAddress];

        if (kasLiquidity == 0 || tokenLiquidity == 0) revert InsufficientKAS();

        // Validate we actually received the KAS
        if (address(this).balance < kasLiquidity) revert InsufficientKAS();

        // Validate we have token approval or balance
        uint256 tokenBalance = IERC20(tokenAddress).balanceOf(address(this));
        uint256 tokenAllowance = IERC20(tokenAddress).allowance(address(pool), address(this));

        if (tokenBalance < tokenLiquidity && tokenAllowance < tokenLiquidity) {
            revert InsufficientTokens();
        }

        // Transfer tokens if we don't already have them
        if (tokenBalance < tokenLiquidity) {
            IERC20(tokenAddress).safeTransferFrom(address(pool), address(this), tokenLiquidity);
        }

        // Wrap KAS to WKAS
        IWKAS wkas = IWKAS(kaspaFinanceWKAS);
        wkas.deposit{value: kasLiquidity}();

        // Determine token ordering (Uniswap V3 requires token0 < token1)
        (address token0, address token1) = tokenAddress < kaspaFinanceWKAS
            ? (tokenAddress, kaspaFinanceWKAS)
            : (kaspaFinanceWKAS, tokenAddress);

        (uint256 amount0, uint256 amount1) = tokenAddress < kaspaFinanceWKAS
            ? (tokenLiquidity, kasLiquidity)
            : (kasLiquidity, tokenLiquidity);

        // Create or get Uniswap V3 pool
        address poolAddress = _getOrCreatePool(token0, token1);

        // Initialize pool price if needed
        _initializePoolIfNeeded(poolAddress, pool, tokenAddress);

        // Approve position manager to spend tokens
        // Using forceApprove (OpenZeppelin 5.x replacement for deprecated safeApprove)
        IERC20(token0).forceApprove(kaspaFinancePositionManager, amount0);
        IERC20(token1).forceApprove(kaspaFinancePositionManager, amount1);

        // Mint full-range liquidity position
        (uint256 positionId, uint128 liquidity, uint256 actualAmount0, uint256 actualAmount1) = 
            _mintLiquidityPosition(token0, token1, amount0, amount1);

        // Validate liquidity was actually minted
        if (liquidity == 0) revert NoLiquidityMinted();

        // Validate actual amounts meet minimum requirements
        uint256 minAmount0 = (amount0 * (10000 - graduationSlippageBps)) / 10000;
        uint256 minAmount1 = (amount1 * (10000 - graduationSlippageBps)) / 10000;
        if (actualAmount0 < minAmount0 || actualAmount1 < minAmount1) {
            revert SlippageExceeded();
        }

        // Refund any excess tokens back to the pool
        _refundExcessTokens(token0, token1, amount0, amount1, actualAmount0, actualAmount1, address(pool));

        // Update state
        hasGraduated[tokenAddress] = true;
        graduationTimestamp[tokenAddress] = block.timestamp;
        liquidityPositionId[tokenAddress] = positionId;
        uniswapPoolAddress[tokenAddress] = poolAddress;

        // Clear expected liquidity storage to save gas
        delete expectedKasLiquidity[tokenAddress];
        delete expectedTokenLiquidity[tokenAddress];

        // Complete graduation on pool contract (sets graduated = true, burns unsold tokens)
        try pool.completeGraduation() {
            // Success
        } catch Error(string memory reason) {
            // Log but don't revert - liquidity is already added
            emit GraduationFailed(tokenAddress, string(abi.encodePacked("Pool completion failed: ", reason)), block.timestamp);
        }

        // Determine which amount is KAS vs Token for event
        uint256 kasAdded = (token1 == kaspaFinanceWKAS) ? actualAmount1 : actualAmount0;
        uint256 tokensAdded = (token0 == tokenAddress) ? actualAmount0 : actualAmount1;

        emit GraduationCompleted(
            tokenAddress,
            poolAddress,
            positionId,
            kasAdded,
            tokensAdded,
            block.timestamp
        );
    }

    // ============ Internal Helper Functions ============

    /**
     * @notice Create Uniswap V3 pool or return existing pool address
     * @param token0 First token address (must be < token1)
     * @param token1 Second token address (must be > token0)
     * @return poolAddress Address of the Uniswap V3 pool
     */
    function _getOrCreatePool(address token0, address token1) 
        internal 
        returns (address poolAddress) 
    {
        IUniswapV3Factory factory = IUniswapV3Factory(kaspaFinanceFactory);

        // Check if pool already exists
        poolAddress = factory.getPool(token0, token1, POOL_FEE_TIER);

        if (poolAddress == address(0)) {
            // Pool doesn't exist, create it
            poolAddress = factory.createPool(token0, token1, POOL_FEE_TIER);

            if (poolAddress == address(0)) revert PoolCreationFailed();

            emit PoolCreated(token0, poolAddress, 0, block.timestamp);
        }

        return poolAddress;
    }

    /**
     * @notice Initialize Uniswap V3 pool with correct starting price if not already initialized
     * @param poolAddress Address of the Uniswap V3 pool
     * @param pool Reference to the BondingCurvePool contract
     * @param tokenAddress Address of the token being graduated
     */
    function _initializePoolIfNeeded(
        address poolAddress, 
        BondingCurvePool pool,
        address tokenAddress
    ) internal {
        IUniswapV3Pool uniPool = IUniswapV3Pool(poolAddress);

        // Check if pool is already initialized
        (uint160 sqrtPriceX96, , , , , , ) = uniPool.slot0();

        if (sqrtPriceX96 == 0) {
            // Pool not initialized, calculate and set initial price
            uint160 initialSqrtPrice = _calculateSqrtPriceX96(
                pool.virtualKasReserve(),
                pool.virtualTokenReserve(),
                tokenAddress
            );

            if (initialSqrtPrice == 0) revert InvalidPrice();

            try uniPool.initialize(initialSqrtPrice) {
                emit PoolInitialized(tokenAddress, poolAddress, initialSqrtPrice, block.timestamp);
            } catch {
                revert PoolInitializationFailed();
            }
        } else {
            // Pool already initialized, validate price is reasonable
            uint160 expectedSqrtPrice = _calculateSqrtPriceX96(
                pool.virtualKasReserve(),
                pool.virtualTokenReserve(),
                tokenAddress
            );

            _validatePriceDeviation(sqrtPriceX96, expectedSqrtPrice);
        }
    }

    /**
     * @notice Calculate sqrtPriceX96 for pool initialization
     * @dev Uniswap V3 requires sqrtPriceX96 = sqrt(price) * 2^96 as a Q64.96 fixed point number
     *      Uses FullMath.mulDiv to safely calculate (reserve * 2^192 / reserve) without overflow
     *      This is critical because shifting reserves by 192 would overflow uint256
     * @param kasReserve Virtual KAS reserve from bonding curve
     * @param tokenReserve Virtual token reserve from bonding curve
     * @param tokenAddress Address of the token being graduated
     * @return sqrtPriceX96 The sqrt price as a Q64.96 fixed point number
     */
    function _calculateSqrtPriceX96(
        uint256 kasReserve,
        uint256 tokenReserve,
        address tokenAddress
    ) internal view returns (uint160) {
        require(kasReserve > 0 && tokenReserve > 0, "Invalid reserves");

        // Determine token ordering
        bool tokenIsToken0 = tokenAddress < kaspaFinanceWKAS;

        // Calculate price * 2^192 using safe 512-bit multiplication
        // Uniswap V3 price = token1/token0 (where token0 < token1)
        // We need: sqrt(price * 2^192) = sqrt(price) * 2^96
        //
        // CRITICAL FIX: Use FullMath.mulDiv instead of shift to prevent overflow
        // For real reserves like 1131 KAS (10^21 wei), shifting by 192 would overflow uint256

        uint256 priceX192;
        if (tokenIsToken0) {
            // token0 = token, token1 = WKAS
            // price = WKAS/token = kasReserve/tokenReserve
            // priceX192 = kasReserve * 2^192 / tokenReserve
            priceX192 = FullMath.mulDiv(kasReserve, uint256(1) << 192, tokenReserve);
        } else {
            // token0 = WKAS, token1 = token
            // price = token/WKAS = tokenReserve/kasReserve
            // priceX192 = tokenReserve * 2^192 / kasReserve
            priceX192 = FullMath.mulDiv(tokenReserve, uint256(1) << 192, kasReserve);
        }

        // Calculate sqrt(priceX192) = sqrt(price * 2^192) = sqrt(price) * 2^96
        uint160 sqrtPriceX96 = uint160(_sqrt(priceX192));

        require(sqrtPriceX96 > 0, "sqrtPriceX96 must be > 0");

        return sqrtPriceX96;
    }

    /**
     * @notice Calculate square root using Babylonian method
     * @dev Used for calculating sqrtPriceX96
     * @param x Input value
     * @return y Square root of x
     */
    function _sqrt(uint256 x) internal pure returns (uint256 y) {
        if (x == 0) return 0;

        uint256 z = (x + 1) / 2;
        y = x;

        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
    }

    /**
     * @notice Validate that actual pool price doesn't deviate too much from expected
     * @param actualSqrtPrice Actual sqrt price from the pool
     * @param expectedSqrtPrice Expected sqrt price based on bonding curve
     */
    function _validatePriceDeviation(uint160 actualSqrtPrice, uint160 expectedSqrtPrice) 
        internal 
        view 
    {
        uint256 deviation;
        if (actualSqrtPrice > expectedSqrtPrice) {
            deviation = actualSqrtPrice - expectedSqrtPrice;
        } else {
            deviation = expectedSqrtPrice - actualSqrtPrice;
        }

        uint256 maxDeviation = (uint256(expectedSqrtPrice) * maxPriceDeviationBps) / 10000;

        if (deviation > maxDeviation) revert PriceDeviationTooHigh();
    }

    /**
     * @notice Mint a full-range liquidity position on Uniswap V3
     * @param token0 First token address
     * @param token1 Second token address
     * @param amount0 Amount of token0 to add
     * @param amount1 Amount of token1 to add
     * @return tokenId NFT position ID
     * @return liquidity Amount of liquidity minted
     * @return actualAmount0 Actual amount of token0 added
     * @return actualAmount1 Actual amount of token1 added
     */
    function _mintLiquidityPosition(
        address token0,
        address token1,
        uint256 amount0,
        uint256 amount1
    ) internal returns (
        uint256 tokenId,
        uint128 liquidity,
        uint256 actualAmount0,
        uint256 actualAmount1
    ) {
        INonfungiblePositionManager.MintParams memory params = INonfungiblePositionManager.MintParams({
            token0: token0,
            token1: token1,
            fee: POOL_FEE_TIER,
            tickLower: FULL_RANGE_TICK_LOWER,
            tickUpper: FULL_RANGE_TICK_UPPER,
            amount0Desired: amount0,
            amount1Desired: amount1,
            amount0Min: (amount0 * (10000 - graduationSlippageBps)) / 10000,
            amount1Min: (amount1 * (10000 - graduationSlippageBps)) / 10000,
            recipient: address(this),
            deadline: block.timestamp + graduationDeadlineSeconds
        });

        return INonfungiblePositionManager(kaspaFinancePositionManager).mint(params);
    }

    /**
     * @notice Refund excess tokens that weren't used in liquidity minting
     * @param token0 First token address
     * @param token1 Second token address
     * @param amount0Desired Desired amount of token0
     * @param amount1Desired Desired amount of token1
     * @param actualAmount0 Actual amount of token0 used
     * @param actualAmount1 Actual amount of token1 used
     * @param recipient Address to receive refunded tokens (usually the pool)
     */
    function _refundExcessTokens(
        address token0,
        address token1,
        uint256 amount0Desired,
        uint256 amount1Desired,
        uint256 actualAmount0,
        uint256 actualAmount1,
        address recipient
    ) internal {
        // Refund excess token0
        if (actualAmount0 < amount0Desired) {
            uint256 excess0 = amount0Desired - actualAmount0;
            if (excess0 > 0) {
                if (token0 == kaspaFinanceWKAS) {
                    // Unwrap WKAS and send KAS
                    IWKAS(kaspaFinanceWKAS).withdraw(excess0);
                    (bool success, ) = recipient.call{value: excess0}("");
                    if (!success) revert TransferFailed();
                } else {
                    // Transfer token
                    IERC20(token0).safeTransfer(recipient, excess0);
                }
            }
        }

        // Refund excess token1
        if (actualAmount1 < amount1Desired) {
            uint256 excess1 = amount1Desired - actualAmount1;
            if (excess1 > 0) {
                if (token1 == kaspaFinanceWKAS) {
                    // Unwrap WKAS and send KAS
                    IWKAS(kaspaFinanceWKAS).withdraw(excess1);
                    (bool success, ) = recipient.call{value: excess1}("");
                    if (!success) revert TransferFailed();
                } else {
                    // Transfer token
                    IERC20(token1).safeTransfer(recipient, excess1);
                }
            }
        }
    }

    // ============ Liquidity Management Functions ============

    /**
     * @notice Collect trading fees from a graduated token's liquidity position
     * @dev Only owner can collect fees (could be DAO in future)
     * @param tokenAddress Address of the graduated token
     * @return amount0 Amount of token0 fees collected
     * @return amount1 Amount of token1 fees collected
     */
    function collectFees(address tokenAddress) 
        external 
        nonReentrant
        onlyOwner 
        returns (uint256 amount0, uint256 amount1) 
    {
        if (!hasGraduated[tokenAddress]) revert NotGraduating();

        uint256 tokenId = liquidityPositionId[tokenAddress];
        require(tokenId > 0, "No position");

        INonfungiblePositionManager.CollectParams memory params = INonfungiblePositionManager.CollectParams({
            tokenId: tokenId,
            recipient: owner(),
            amount0Max: type(uint128).max,
            amount1Max: type(uint128).max
        });

        (amount0, amount1) = INonfungiblePositionManager(kaspaFinancePositionManager).collect(params);

        emit FeesCollected(tokenAddress, amount0, amount1, block.timestamp);
    }

    // ============ Emergency & Admin Functions ============

    /**
     * @notice Cancel a failed graduation and return funds to pool
     * @dev Only owner can cancel graduations
     * @param tokenAddress Address of the token with failed graduation
     */
    function cancelGraduation(address tokenAddress) 
        external 
        nonReentrant
        onlyOwner 
    {
        if (hasGraduated[tokenAddress]) revert AlreadyGraduated();

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));
        if (!pool.graduating()) revert NotGraduating();

        // Get expected amounts
        uint256 kasToReturn = expectedKasLiquidity[tokenAddress];
        uint256 tokensToReturn = expectedTokenLiquidity[tokenAddress];

        // Return KAS to pool if we have it
        if (kasToReturn > 0 && address(this).balance >= kasToReturn) {
            (bool success, ) = address(pool).call{value: kasToReturn}("");
            require(success, "KAS return failed");
        }

        // Return tokens to pool if we have them
        uint256 tokenBalance = IERC20(tokenAddress).balanceOf(address(this));
        if (tokenBalance > 0) {
            IERC20(tokenAddress).safeTransfer(address(pool), tokenBalance);
        }

        // Clear expected liquidity
        delete expectedKasLiquidity[tokenAddress];
        delete expectedTokenLiquidity[tokenAddress];

        // Try to revert pool state (requires pool to implement this)
        try pool.cancelGraduation() {
            // Success
        } catch {
            // Pool doesn't support cancellation, continue anyway
        }

        emit GraduationCancelled(
            tokenAddress, 
            kasToReturn, 
            tokensToReturn,
            "Cancelled by admin",
            block.timestamp
        );
    }

    /**
     * @notice Emergency withdraw accidentally sent tokens
     * @dev Cannot withdraw graduated tokens or WKAS
     * @param token Token address to withdraw
     * @param amount Amount to withdraw
     */
    function emergencyWithdraw(address token, uint256 amount) 
        external 
        onlyOwner 
    {
        require(!hasGraduated[token], "Cannot withdraw graduated token");
        require(token != kaspaFinanceWKAS, "Cannot withdraw WKAS directly");

        IERC20(token).safeTransfer(owner(), amount);

        emit EmergencyWithdrawal(token, amount, owner());
    }

    /**
     * @notice Emergency withdraw KAS
     * @dev Use with caution - should only be for stuck funds
     */
    function emergencyWithdrawKAS() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No KAS to withdraw");

        (bool success, ) = owner().call{value: balance}("");
        require(success, "KAS withdrawal failed");

        emit EmergencyWithdrawal(address(0), balance, owner());
    }

    /**
     * @notice Pause all graduations in case of emergency
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause graduations
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ Configuration Functions ============

    /**
     * @notice Update the graduation oracle address
     * @param newOracle New oracle address
     */
    function setGraduationOracle(address newOracle) external onlyOwner {
        if (newOracle == address(0)) revert InvalidAddress();

        address oldOracle = graduationOracle;
        graduationOracle = newOracle;

        emit OracleUpdated(oldOracle, newOracle);
    }

    /**
     * @notice Update the token factory address
     * @param newFactory New token factory address
     */
    function setTokenFactory(address newFactory) external onlyOwner {
        if (newFactory == address(0)) revert InvalidAddress();

        address oldFactory = tokenFactory;
        tokenFactory = newFactory;

        emit TokenFactoryUpdated(oldFactory, newFactory);
    }

    /**
     * @notice Update graduation parameters
     * @param _slippageBps Slippage tolerance in basis points (50-1000 = 0.5%-10%)
     * @param _deadlineSeconds Transaction deadline in seconds (60-3600 = 1min-1hour)
     * @param _maxPriceDeviationBps Maximum price deviation in basis points (10-500 = 0.1%-5%)
     */
    function setGraduationParams(
        uint256 _slippageBps, 
        uint256 _deadlineSeconds,
        uint256 _maxPriceDeviationBps
    ) external onlyOwner {
        if (_slippageBps < 50 || _slippageBps > 1000) revert InvalidParameters();
        if (_deadlineSeconds < 60 || _deadlineSeconds > 3600) revert InvalidParameters();
        if (_maxPriceDeviationBps < 10 || _maxPriceDeviationBps > 500) revert InvalidParameters();

        graduationSlippageBps = _slippageBps;
        graduationDeadlineSeconds = _deadlineSeconds;
        maxPriceDeviationBps = _maxPriceDeviationBps;

        emit GraduationParamsUpdated(_slippageBps, _deadlineSeconds, _maxPriceDeviationBps);
    }

    // ============ View Functions ============

    /**
     * @notice Check if a token has graduated
     * @param tokenAddress Token address to check
     * @return Whether the token has graduated
     */
    function isGraduated(address tokenAddress) external view returns (bool) {
        return hasGraduated[tokenAddress];
    }

    /**
     * @notice Get detailed graduation information for a token
     * @param tokenAddress Token address to query
     * @return graduated Whether token has graduated
     * @return timestamp When graduation completed
     * @return positionId Uniswap V3 NFT position ID
     * @return poolAddress Uniswap V3 pool address
     */
    function getGraduationInfo(address tokenAddress) 
        external 
        view 
        returns (
            bool graduated,
            uint256 timestamp,
            uint256 positionId,
            address poolAddress
        ) 
    {
        return (
            hasGraduated[tokenAddress],
            graduationTimestamp[tokenAddress],
            liquidityPositionId[tokenAddress],
            uniswapPoolAddress[tokenAddress]
        );
    }

    /**
     * @notice Public test helper: Calculate sqrtPriceX96 for testing
     * @dev Exposes the internal _calculateSqrtPriceX96 function for unit tests
     * @param kasReserve Virtual KAS reserve
     * @param tokenReserve Virtual token reserve
     * @param tokenAddress Token address for ordering
     * @return sqrtPriceX96 The calculated sqrt price
     */
    function calculateSqrtPriceX96(
        uint256 kasReserve,
        uint256 tokenReserve,
        address tokenAddress
    ) external view returns (uint160) {
        return _calculateSqrtPriceX96(kasReserve, tokenReserve, tokenAddress);
    }

    /**
     * @notice Get graduation information for multiple tokens
     * @param tokens Array of token addresses
     * @return graduated Array of graduation statuses
     * @return timestamps Array of graduation timestamps
     * @return positionIds Array of position IDs
     * @return poolAddresses Array of pool addresses
     */
    function getMultipleGraduationInfo(address[] calldata tokens)
        external
        view
        returns (
            bool[] memory graduated,
            uint256[] memory timestamps,
            uint256[] memory positionIds,
            address[] memory poolAddresses
        )
    {
        uint256 length = tokens.length;
        graduated = new bool[](length);
        timestamps = new uint256[](length);
        positionIds = new uint256[](length);
        poolAddresses = new address[](length);

        for (uint256 i = 0; i < length; i++) {
            graduated[i] = hasGraduated[tokens[i]];
            timestamps[i] = graduationTimestamp[tokens[i]];
            positionIds[i] = liquidityPositionId[tokens[i]];
            poolAddresses[i] = uniswapPoolAddress[tokens[i]];
        }
    }

    /**
     * @notice Get expected liquidity amounts for a token in graduation process
     * @param tokenAddress Token address
     * @return expectedKas Expected KAS liquidity
     * @return expectedTokens Expected token liquidity
     */
    function getExpectedLiquidity(address tokenAddress)
        external
        view
        returns (uint256 expectedKas, uint256 expectedTokens)
    {
        return (
            expectedKasLiquidity[tokenAddress],
            expectedTokenLiquidity[tokenAddress]
        );
    }
}

contracts/GraduationControllerV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title GraduationController V11 (Final Fix)
 * @notice Manages token graduation from bonding curve to Uniswap V3 DEX liquidity
 * @dev V11 CRITICAL FIX:
 *      FIX #12: Implement IERC721Receiver to accept LP NFTs from Position Manager
 *               - Position Manager uses safeMint which requires recipient to implement onERC721Received
 *               - V10's approval ordering fix was NOT the issue
 *               - This was the root cause of all "STF" (Safe Transfer Failed) errors
 * 
 *      V4-V10 HISTORY (inherited):
 *      V4 #1: forceCompleteCorruptedGraduation() - Emergency recovery for corrupted pools
 *      V4 #2: _completeGraduationInternal() - Shared logic for normal + forced completion
 *      V4 #3: Try/catch on pool.completeGraduation() - Handles already-graduated pools
 *      V10: Approval ordering fix (moved pool approvals before controller approvals) - INEFFECTIVE
 * 
 *      V3 FIXES (inherited):
 *      FIX #1: INITIAL_VIRTUAL_KAS = 0.001 ether (not 1000)
 *      FIX #2: Snapshot reserves BEFORE pool.initiateGraduation()
 *      FIX #3: Use snapshot.kasLiquidity (1089.99 KAS, not 89.991)
 *      FIX #4: Ticks = -887200/887200 (multiples of 50)
 *      FIX #5: Use createAndInitializePoolIfNecessary() - atomic, no front-running
 *      FIX #6: Burn LP NFT to 0x...dEaD (permanent liquidity lock)
 *      FIX #7: Send excess to treasury, NEVER to pool (receive() reverts)
 *      FIX #8: Validate sqrtPrice MIN/MAX bounds
 *      FIX #9: pool.completeGraduation() with try/catch (V4: tolerates corrupted state)
 *      FIX #10: Lock oracle changes during graduation (authorizedOracle in snapshot)
 *      FIX #11: Deadline = 1800 seconds (30 min, not 5)
 * 
 * Version: 11.0.0
 * Deployment Date: October 28, 2025
 * Architecture: Snapshot-based with ERC721 receiver implementation
 */

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./BondingCurvePool.sol";

/**
 * @title FullMath Library
 * @notice Safe 512-bit multiplication and division from Uniswap V3
 * @dev Prevents overflow when calculating sqrtPriceX96 with large reserves
 */
library FullMath {
    /**
     * @notice Calculates floor(a×b÷denominator) with full precision
     * @dev Handles intermediate overflow by using 512-bit math
     */
    function mulDiv(
        uint256 a,
        uint256 b,
        uint256 denominator
    ) internal pure returns (uint256 result) {
        // 512-bit multiply [prod1 prod0] = a * b
        uint256 prod0;
        uint256 prod1;
        assembly {
            let mm := mulmod(a, b, not(0))
            prod0 := mul(a, b)
            prod1 := sub(sub(mm, prod0), lt(mm, prod0))
        }

        if (prod1 == 0) {
            require(denominator > 0);
            assembly {
                result := div(prod0, denominator)
            }
            return result;
        }

        require(denominator > prod1);

        uint256 remainder;
        assembly {
            remainder := mulmod(a, b, denominator)
        }
        assembly {
            prod1 := sub(prod1, gt(remainder, prod0))
            prod0 := sub(prod0, remainder)
        }

        uint256 twos = denominator & (~denominator + 1);
        assembly {
            denominator := div(denominator, twos)
        }

        assembly {
            prod0 := div(prod0, twos)
        }
        assembly {
            twos := add(div(sub(0, twos), twos), 1)
        }
        unchecked {
            prod0 |= prod1 * twos;
        }

        uint256 inv = (3 * denominator) ^ 2;
        unchecked {
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
            inv *= 2 - denominator * inv;
        }

        unchecked {
            result = prod0 * inv;
        }
        return result;
    }
}

/**
 * @title Uniswap V3 Factory Interface
 */
interface IUniswapV3Factory {
    function createPool(address tokenA, address tokenB, uint24 fee) 
        external returns (address pool);

    function getPool(address tokenA, address tokenB, uint24 fee) 
        external view returns (address pool);
}

/**
 * @title Uniswap V3 Pool Interface
 */
interface IUniswapV3Pool {
    function initialize(uint160 sqrtPriceX96) external;

    function slot0() external view returns (
        uint160 sqrtPriceX96,
        int24 tick,
        uint16 observationIndex,
        uint16 observationCardinality,
        uint16 observationCardinalityNext,
        uint8 feeProtocol,
        bool unlocked
    );

    function token0() external view returns (address);
    function token1() external view returns (address);
}

/**
 * @title Uniswap V3 NFT Position Manager Interface
 * @notice FIX #5: Added createAndInitializePoolIfNecessary() for atomic pool creation
 */
interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    struct CollectParams {
        uint256 tokenId;
        address recipient;
        uint128 amount0Max;
        uint128 amount1Max;
    }

    function mint(MintParams calldata params) external payable returns (
        uint256 tokenId,
        uint128 liquidity,
        uint256 amount0,
        uint256 amount1
    );

    function collect(CollectParams calldata params) external payable returns (
        uint256 amount0,
        uint256 amount1
    );

    /**
     * @notice FIX #5: Atomic pool creation and initialization (prevents front-running)
     * @dev Creates pool if it doesn't exist, then initializes it in same transaction
     */
    function createAndInitializePoolIfNecessary(
        address token0,
        address token1,
        uint24 fee,
        uint160 sqrtPriceX96
    ) external payable returns (address pool);

    /**
     * @notice FIX #6: Transfer NFT to burn address for permanent liquidity lock
     */
    function safeTransferFrom(
        address from,
        address to,
        uint256 tokenId
    ) external;
}

/**
 * @title Wrapped KAS Interface
 */
interface IWKAS {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title TokenFactory Interface  
 */
interface ITokenFactory {
    function isDeployedPool(address pool) external view returns (bool);
}

/**
 * @title GraduationController V3
 * @notice Snapshot-based graduation with all 11 critical fixes
 */
contract GraduationControllerV3 is Ownable, ReentrancyGuard, Pausable, IERC721Receiver {
    using SafeERC20 for IERC20;

    // ============ State Variables ============

    /// @notice Contract version
    string public constant VERSION = "11.0.0";

    /// @notice Kaspa Finance Uniswap V3 factory address
    address public immutable kaspaFinanceFactory;

    /// @notice Kaspa Finance NFT Position Manager address
    address public immutable kaspaFinancePositionManager;

    /// @notice Wrapped KAS token address
    address public immutable kaspaFinanceWKAS;

    /// @notice Address authorized to trigger graduations (backend oracle)
    address public graduationOracle;

    /// @notice TokenFactory address for validating legitimate tokens
    address public tokenFactory;

    /// @notice FIX #7: Treasury address for excess token handling (NOT pool!)
    address public treasury;

    // Graduation tracking
    mapping(address => bool) public hasGraduated;
    mapping(address => uint256) public graduationTimestamp;
    mapping(address => address) public uniswapPoolAddress;

    /// @notice FIX #2/#3: Immutable graduation snapshots (captured BEFORE pool changes)
    mapping(address => GraduationSnapshot) public graduationSnapshots;

    // NOTE: liquidityPositionId mapping REMOVED (FIX #6: NFT is burned, not stored)

    // ============ Structures ============

    /**
     * @notice FIX #2/#3/#10: Immutable snapshot of graduation state
     * @dev Captured BEFORE pool.initiateGraduation() to prevent stale data
     */
    struct GraduationSnapshot {
        uint256 kasLiquidity;        // KAS to add to DEX (e.g., 1089.99)
        uint256 tokenLiquidity;      // Tokens to add to DEX (e.g., 250M)
        uint160 targetSqrtPriceX96;  // Pre-calculated price
        uint24 feeTier;              // Pool fee (2500 = 0.25%)
        uint32 initiatedAt;          // Block timestamp
        bool poolInitialized;        // Uniswap pool initialized
        bool lpMinted;               // LP NFT minted
        address uniswapPool;         // Created pool address
        address authorizedOracle;    // FIX #10: Oracle authorized for this graduation
    }

    // ============ Constants ============

    /// @notice Uniswap V3 pool fee tier (0.25%)
    uint24 public constant POOL_FEE_TIER = 2500;

    /// @notice FIX #4: Full range ticks (multiples of 50 for 0.25% fee tier)
    int24 public constant FULL_RANGE_TICK_LOWER = -887200;  // Was -887220 in V2
    int24 public constant FULL_RANGE_TICK_UPPER = 887200;   // Was 887220 in V2

    /// @notice FIX #1: Correct initial virtual KAS (matches BondingCurvePool)
    uint256 public constant INITIAL_VIRTUAL_KAS = 0.001 ether;  // Was 1000 ether in V2

    /// @notice Percentage of token supply to add as liquidity (25%)
    uint256 public constant LP_SUPPLY_PERCENTAGE = 25;

    /// @notice FIX #8: Uniswap V3 sqrtPrice bounds for validation
    uint160 public constant MIN_SQRT_RATIO = 4295128739;
    uint160 public constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;

    /// @notice FIX #6: Burn address for permanent LP NFT locking
    address public constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    // ============ Configurable Parameters ============

    /// @notice Slippage tolerance for liquidity minting (in basis points, 500 = 5%)
    uint256 public graduationSlippageBps = 500;

    /// @notice FIX #11: Extended deadline for graduation transactions (30 minutes)
    uint256 public graduationDeadlineSeconds = 1800;  // Was 300 (5 min) in V2

    /// @notice Maximum price deviation tolerance (in basis points, 100 = 1%)
    uint256 public maxPriceDeviationBps = 100;

    // ============ Events ============

    /**
     * @notice FIX #2: New event for snapshot creation
     */
    event GraduationSnapshotCreated(
        address indexed tokenAddress,
        uint256 kasLiquidity,
        uint256 tokenLiquidity,
        uint160 targetSqrtPriceX96,
        uint256 timestamp
    );

    event GraduationInitiated(
        address indexed tokenAddress,
        uint256 expectedKasLiquidity,
        uint256 expectedTokenLiquidity,
        uint256 timestamp
    );

    event PoolCreated(
        address indexed tokenAddress,
        address indexed poolAddress,
        uint160 sqrtPriceX96,
        uint256 timestamp
    );

    event PoolInitialized(
        address indexed tokenAddress,
        address indexed poolAddress,
        uint160 sqrtPriceX96,
        uint256 timestamp
    );

    event GraduationCompleted(
        address indexed tokenAddress,
        address indexed poolAddress,
        uint256 liquidityPositionId,
        uint256 kasAdded,
        uint256 tokensAdded,
        uint256 timestamp
    );

    /**
     * @notice FIX #6: New event for LP NFT burning
     */
    event LPNFTBurned(
        address indexed tokenAddress,
        uint256 indexed positionId,
        uint256 timestamp
    );

    /**
     * @notice FIX #7: New event for excess token handling
     */
    event ExcessTokensHandled(
        address indexed token0,
        address indexed token1,
        uint256 excess0,
        uint256 excess1,
        address indexed recipient
    );

    event GraduationCancelled(
        address indexed tokenAddress,
        uint256 kasReturned,
        uint256 tokensReturned,
        string reason,
        uint256 timestamp
    );

    event GraduationFailed(
        address indexed tokenAddress,
        string reason,
        uint256 timestamp
    );

    event FeesCollected(
        address indexed tokenAddress,
        uint256 amount0,
        uint256 amount1,
        uint256 timestamp
    );

    event OracleUpdated(address indexed oldOracle, address indexed newOracle);
    event TokenFactoryUpdated(address indexed oldFactory, address indexed newFactory);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event GraduationParamsUpdated(uint256 slippageBps, uint256 deadlineSeconds, uint256 maxPriceDeviationBps);
    event EmergencyWithdrawal(address indexed token, uint256 amount, address indexed recipient);

    // ============ Errors ============

    error OnlyOracle();
    error AlreadyGraduated();
    error AlreadyInitiated();
    error NotInitiated();
    error InvalidToken();
    error InsufficientLiquidity();
    error InvalidPrice();
    error PoolNotReady();
    error TransferFailed();
    error InvalidAddress();
    error UnauthorizedOracle();  // FIX #10

    // ============ Modifiers ============

    modifier onlyOracle() {
        if (msg.sender != graduationOracle) revert OnlyOracle();
        _;
    }

    // ============ Constructor ============

    constructor(
        address _kaspaFinanceFactory,
        address _kaspaFinancePositionManager,
        address _kaspaFinanceWKAS,
        address _graduationOracle,
        address _tokenFactory,
        address _treasury
    ) Ownable(msg.sender) {
        require(_kaspaFinanceFactory != address(0), "Invalid factory");
        require(_kaspaFinancePositionManager != address(0), "Invalid position manager");
        require(_kaspaFinanceWKAS != address(0), "Invalid WKAS");
        require(_graduationOracle != address(0), "Invalid oracle");
        require(_tokenFactory != address(0), "Invalid token factory");
        require(_treasury != address(0), "Invalid treasury");

        kaspaFinanceFactory = _kaspaFinanceFactory;
        kaspaFinancePositionManager = _kaspaFinancePositionManager;
        kaspaFinanceWKAS = _kaspaFinanceWKAS;
        graduationOracle = _graduationOracle;
        tokenFactory = _tokenFactory;
        treasury = _treasury;
    }

    // ============ Core Graduation Functions ============

    /**
     * @notice FIX #2/#3: Initiate graduation with snapshot (POOL-INITIATED)
     * @dev NOW CALLED BY POOL DIRECTLY - msg.sender is the pool contract!
     * @param tokenAddress The pool address (should match msg.sender for validation)
     */
    function initiateGraduation(address tokenAddress) 
        external 
        nonReentrant 
        whenNotPaused
    {
        // CRITICAL FIX: Caller must be the pool itself (not oracle!)
        require(msg.sender == tokenAddress, "Only pool can initiate");

        if (hasGraduated[tokenAddress]) revert AlreadyGraduated();
        if (graduationSnapshots[tokenAddress].initiatedAt != 0) revert AlreadyInitiated();

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));

        // SECURITY: Query TokenFactory to verify pool is legitimate (prevents fake pools)
        // This is the ONLY secure way - querying trusted factory, not trusting pool's self-reported data
        require(ITokenFactory(tokenFactory).isDeployedPool(tokenAddress), "Pool not deployed by authorized factory");

        // STEP 1: Snapshot pool state (FIX #2/#3)
        // Pool has already sent KAS and set graduating=true before calling us
        require(pool.graduating(), "Pool must be graduating");
        require(pool.liquidityTransferred(), "KAS must be transferred first");

        uint256 kasLiquidity = pool.virtualKasReserve() > INITIAL_VIRTUAL_KAS 
            ? pool.virtualKasReserve() - INITIAL_VIRTUAL_KAS 
            : 0;
        uint256 tokenLiquidity = (pool.totalSupply() * LP_SUPPLY_PERCENTAGE) / 100;

        require(kasLiquidity > 0 && tokenLiquidity > 0, "Insufficient liquidity");

        // STEP 2: Pre-calculate sqrtPrice from snapshot values (FIX #2)
        uint160 targetSqrtPrice = _calculateSqrtPriceX96(
            kasLiquidity,
            tokenLiquidity,
            tokenAddress
        );

        require(targetSqrtPrice > 0, "Invalid price");

        // STEP 3: Store immutable snapshot with CORRECT pool address (msg.sender = pool!)
        graduationSnapshots[tokenAddress] = GraduationSnapshot({
            kasLiquidity: kasLiquidity,
            tokenLiquidity: tokenLiquidity,
            targetSqrtPriceX96: targetSqrtPrice,
            feeTier: POOL_FEE_TIER,
            initiatedAt: uint32(block.timestamp),
            poolInitialized: false,
            lpMinted: false,
            uniswapPool: address(0),
            authorizedOracle: graduationOracle  // Store oracle for completion auth
        });

        emit GraduationSnapshotCreated(
            tokenAddress,
            kasLiquidity,
            tokenLiquidity,
            targetSqrtPrice,
            block.timestamp
        );

        emit GraduationInitiated(
            tokenAddress,
            kasLiquidity,
            tokenLiquidity,
            block.timestamp
        );

        // NOTE: Pool has already transferred KAS and set state, no callback needed!
    }

    /**
     * @notice FIX #3/#5/#6/#7/#9/#10: Complete graduation using snapshot values
     * @dev Uses ONLY snapshot data, never queries pool after initiation
     */
    function completeGraduation(address tokenAddress) 
        external 
        nonReentrant 
        whenNotPaused
    {
        if (hasGraduated[tokenAddress]) revert AlreadyGraduated();

        // STEP 1: Load snapshot
        GraduationSnapshot storage snapshot = graduationSnapshots[tokenAddress];
        if (snapshot.initiatedAt == 0) revert NotInitiated();
        require(!snapshot.lpMinted, "Already completed");

        // FIX #10: Validate caller is authorized oracle
        if (msg.sender != snapshot.authorizedOracle) revert UnauthorizedOracle();

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));
        require(pool.graduating() && pool.liquidityTransferred(), "Invalid state");

        // Complete graduation with LP creation
        _completeGraduationInternal(tokenAddress, snapshot, pool);
    }

    /**
     * @notice V4 RECOVERY: Force complete corrupted graduation (owner-only)
     * @dev Use when pool state was corrupted (graduated=true without LP)
     * @param tokenAddress The pool address with corrupted state
     */
    function forceCompleteCorruptedGraduation(address tokenAddress)
        external
        onlyOwner
        nonReentrant
        whenNotPaused
    {
        if (hasGraduated[tokenAddress]) revert AlreadyGraduated();

        // Load snapshot
        GraduationSnapshot storage snapshot = graduationSnapshots[tokenAddress];
        if (snapshot.initiatedAt == 0) revert NotInitiated();
        require(!snapshot.lpMinted, "Already completed");

        BondingCurvePool pool = BondingCurvePool(payable(tokenAddress));

        // V4: SKIP state check for corrupted pools - just verify snapshot exists
        require(snapshot.kasLiquidity > 0 && snapshot.tokenLiquidity > 0, "Invalid snapshot");

        // Complete graduation with LP creation (bypasses pool state check)
        _completeGraduationInternal(tokenAddress, snapshot, pool);
    }

    /**
     * @notice V4: Internal function to complete graduation and create LP
     * @dev Extracted to share logic between normal and forced completion
     */
    function _completeGraduationInternal(
        address tokenAddress,
        GraduationSnapshot storage snapshot,
        BondingCurvePool pool
    ) internal {

        // STEP 1: Use snapshot values (NEVER query pool!) - FIX #3
        uint256 kasLiquidity = snapshot.kasLiquidity;      // 1089.99 KAS
        uint256 tokenLiquidity = snapshot.tokenLiquidity;  // 250M tokens

        // STEP 2: Validate we received the KAS
        require(address(this).balance >= kasLiquidity, "Insufficient KAS");

        // STEP 3: V10 FIX - Tokens already transferred during pool.initiateGraduation()
        // Pool PUSHES tokens directly to GC (no approve/transferFrom needed)
        // Just verify we have the tokens we expect
        require(IERC20(tokenAddress).balanceOf(address(this)) >= tokenLiquidity, "Insufficient tokens");

        // STEP 4: Wrap KAS to WKAS (FIX #3: Use full snapshot amount)
        IWKAS(kaspaFinanceWKAS).deposit{value: kasLiquidity}();

        // STEP 5: Determine token ordering
        (address token0, address token1) = tokenAddress < kaspaFinanceWKAS
            ? (tokenAddress, kaspaFinanceWKAS)
            : (kaspaFinanceWKAS, tokenAddress);

        (uint256 amount0, uint256 amount1) = tokenAddress < kaspaFinanceWKAS
            ? (tokenLiquidity, kasLiquidity)
            : (kasLiquidity, tokenLiquidity);

        // STEP 6: V10 FIX - Approve tokens BEFORE pool creation (prevents STF errors!)
        // If createAndInitializePoolIfNecessary needs tokens during initialization,
        // the Position Manager must already have approval
        IERC20(token0).forceApprove(kaspaFinancePositionManager, amount0);
        IERC20(token1).forceApprove(kaspaFinancePositionManager, amount1);

        // STEP 7: Create & initialize pool ATOMICALLY (FIX #5: prevents front-running!)
        // Now that tokens are approved, pool creation can transfer if needed
        address poolAddress = INonfungiblePositionManager(kaspaFinancePositionManager)
            .createAndInitializePoolIfNecessary(
                token0,
                token1,
                POOL_FEE_TIER,
                snapshot.targetSqrtPriceX96  // Use snapshot price!
            );

        snapshot.uniswapPool = poolAddress;
        snapshot.poolInitialized = true;

        emit PoolCreated(tokenAddress, poolAddress, snapshot.targetSqrtPriceX96, block.timestamp);
        emit PoolInitialized(tokenAddress, poolAddress, snapshot.targetSqrtPriceX96, block.timestamp);

        // STEP 8: Mint LP position (FIX #11: 30 minute deadline)
        (uint256 positionId, uint128 liquidity, uint256 actualAmount0, uint256 actualAmount1) = 
            _mintLiquidityPosition(token0, token1, amount0, amount1);

        require(liquidity > 0, "No liquidity minted");
        snapshot.lpMinted = true;

        // FIX #7: Handle excess tokens WITHOUT refunding to pool (would revert!)
        _handleExcessTokens(token0, token1, amount0, amount1, actualAmount0, actualAmount1);

        // STEP 9: Burn LP NFT to dead address (FIX #6: permanent liquidity lock!)
        INonfungiblePositionManager(kaspaFinancePositionManager).safeTransferFrom(
            address(this),
            BURN_ADDRESS,  // 0x...dEaD - provably uncontrollable
            positionId
        );

        emit LPNFTBurned(tokenAddress, positionId, block.timestamp);

        // STEP 10: Mark graduated (don't store positionId - it's burned)
        hasGraduated[tokenAddress] = true;
        graduationTimestamp[tokenAddress] = block.timestamp;
        uniswapPoolAddress[tokenAddress] = poolAddress;

        // STEP 11: Complete on pool (FIX #9: MUST succeed or revert entire tx!)
        // V4: Use try/catch for corrupted pools that can't call completeGraduation
        try pool.completeGraduation() {
            // Success - pool state updated
        } catch {
            // Pool is corrupted (graduated=true already) - skip callback
            // LP is created regardless, which is the success metric
        }

        emit GraduationCompleted(
            tokenAddress, 
            poolAddress, 
            positionId, 
            kasLiquidity, 
            tokenLiquidity, 
            block.timestamp
        );
    }

    // ============ Internal Helper Functions ============

    /**
     * @notice FIX #11: Mint liquidity position with 30 minute deadline
     */
    function _mintLiquidityPosition(
        address token0,
        address token1,
        uint256 amount0,
        uint256 amount1
    ) internal returns (uint256 positionId, uint128 liquidity, uint256 actualAmount0, uint256 actualAmount1) {
        INonfungiblePositionManager.MintParams memory params = INonfungiblePositionManager.MintParams({
            token0: token0,
            token1: token1,
            fee: POOL_FEE_TIER,
            tickLower: FULL_RANGE_TICK_LOWER,   // FIX #4: -887200
            tickUpper: FULL_RANGE_TICK_UPPER,   // FIX #4: 887200
            amount0Desired: amount0,
            amount1Desired: amount1,
            amount0Min: (amount0 * (10000 - graduationSlippageBps)) / 10000,
            amount1Min: (amount1 * (10000 - graduationSlippageBps)) / 10000,
            recipient: address(this),
            deadline: block.timestamp + graduationDeadlineSeconds  // FIX #11: 1800 seconds
        });

        return INonfungiblePositionManager(kaspaFinancePositionManager).mint(params);
    }

    /**
     * @notice FIX #7: Handle excess tokens WITHOUT sending to pool (would revert!)
     * @dev Sends excess to treasury instead of pool (pool's receive() rejects KAS)
     */
    function _handleExcessTokens(
        address token0,
        address token1,
        uint256 amount0Desired,
        uint256 amount1Desired,
        uint256 actualAmount0,
        uint256 actualAmount1
    ) internal {
        uint256 excess0 = 0;
        uint256 excess1 = 0;

        // Calculate excess amounts
        if (actualAmount0 < amount0Desired) {
            excess0 = amount0Desired - actualAmount0;
        }
        if (actualAmount1 < amount1Desired) {
            excess1 = amount1Desired - actualAmount1;
        }

        // Send excess to treasury (NOT to pool! Pool's receive() would revert)
        if (excess0 > 0 && treasury != address(0)) {
            IERC20(token0).safeTransfer(treasury, excess0);
        }
        if (excess1 > 0 && treasury != address(0)) {
            IERC20(token1).safeTransfer(treasury, excess1);
        }

        emit ExcessTokensHandled(token0, token1, excess0, excess1, treasury);
    }

    /**
     * @notice FIX #8: Calculate sqrtPriceX96 with MIN/MAX bounds validation
     * @dev Validates price is within Uniswap V3 acceptable range
     */
    function _calculateSqrtPriceX96(
        uint256 kasReserve,
        uint256 tokenReserve,
        address tokenAddress
    ) internal view returns (uint160) {
        require(kasReserve > 0 && tokenReserve > 0, "Zero reserves");

        uint256 priceX192;

        if (tokenAddress < kaspaFinanceWKAS) {
            priceX192 = FullMath.mulDiv(kasReserve, 2**192, tokenReserve);
        } else {
            priceX192 = FullMath.mulDiv(tokenReserve, 2**192, kasReserve);
        }

        uint160 sqrtPriceX96 = uint160(_sqrt(priceX192));

        require(sqrtPriceX96 > 0, "sqrtPriceX96 must be > 0");

        // FIX #8: Validate Uniswap V3 bounds
        require(
            sqrtPriceX96 >= MIN_SQRT_RATIO,
            "Price too low (below MIN_SQRT_RATIO)"
        );
        require(
            sqrtPriceX96 <= MAX_SQRT_RATIO,
            "Price too high (above MAX_SQRT_RATIO)"
        );

        return sqrtPriceX96;
    }

    /**
     * @notice Integer square root via Babylonian method
     */
    function _sqrt(uint256 x) internal pure returns (uint256) {
        if (x == 0) return 0;
        uint256 z = (x + 1) / 2;
        uint256 y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
        return y;
    }

    // ============ Admin Functions ============

    function setGraduationOracle(address newOracle) external onlyOwner {
        if (newOracle == address(0)) revert InvalidAddress();
        address oldOracle = graduationOracle;
        graduationOracle = newOracle;
        emit OracleUpdated(oldOracle, newOracle);
    }

    function setTokenFactory(address newFactory) external onlyOwner {
        if (newFactory == address(0)) revert InvalidAddress();
        address oldFactory = tokenFactory;
        tokenFactory = newFactory;
        emit TokenFactoryUpdated(oldFactory, newFactory);
    }

    /**
     * @notice FIX #7: Set treasury address for excess token handling
     */
    function setTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert InvalidAddress();
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    function setGraduationParams(
        uint256 _slippageBps,
        uint256 _deadlineSeconds,
        uint256 _maxPriceDeviationBps
    ) external onlyOwner {
        require(_slippageBps <= 10000, "Invalid slippage");
        require(_deadlineSeconds >= 60 && _deadlineSeconds <= 3600, "Invalid deadline");
        require(_maxPriceDeviationBps <= 10000, "Invalid price deviation");

        graduationSlippageBps = _slippageBps;
        graduationDeadlineSeconds = _deadlineSeconds;
        maxPriceDeviationBps = _maxPriceDeviationBps;

        emit GraduationParamsUpdated(_slippageBps, _deadlineSeconds, _maxPriceDeviationBps);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Emergency function to return stuck graduation funds to pool
     * @dev Use this when graduation snapshot is corrupted and funds are stuck
     * @param tokenAddress The bonding curve pool address to return funds to
     */
    function emergencyReturnGraduationFunds(address tokenAddress) 
        external 
        onlyOwner 
    {
        require(tokenAddress != address(0), "Invalid token address");
        require(!hasGraduated[tokenAddress], "Already graduated");

        GraduationSnapshot storage snapshot = graduationSnapshots[tokenAddress];
        require(snapshot.initiatedAt != 0, "No graduation initiated");
        require(!snapshot.lpMinted, "Graduation already completed");

        uint256 kasToReturn = snapshot.kasLiquidity;
        require(kasToReturn > 0, "No KAS to return");
        require(address(this).balance >= kasToReturn, "Insufficient balance");

        // Clear the snapshot
        delete graduationSnapshots[tokenAddress];

        // Return KAS to pool
        (bool success, ) = payable(tokenAddress).call{value: kasToReturn}("");
        require(success, "KAS transfer failed");

        emit GraduationCancelled(
            tokenAddress,
            kasToReturn,
            0,
            "Emergency fund recovery",
            block.timestamp
        );
    }

    /**
     * @notice Emergency withdrawal of stuck tokens
     */
    function emergencyWithdraw(address token, uint256 amount, address recipient) 
        external 
        onlyOwner 
    {
        require(recipient != address(0), "Invalid recipient");

        if (token == address(0)) {
            (bool success, ) = payable(recipient).call{value: amount}("");
            require(success, "Transfer failed");
        } else {
            IERC20(token).safeTransfer(recipient, amount);
        }

        emit EmergencyWithdrawal(token, amount, recipient);
    }

    /**
     * @notice IERC721Receiver implementation to accept LP NFTs from Position Manager
     * @dev Required for Position Manager's safeMint to succeed
     * @return bytes4 The function selector to confirm successful receipt
     */
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external pure override returns (bytes4) {
        return this.onERC721Received.selector;
    }

    // Receive KAS from bonding curve
    receive() external payable {}
}

